window.ANSWER_TERMS = {"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"fagocytose":{"title":"Fagocytose","short":"Het 'opeten' van grote deeltjes of hele cellen (zoals bacteriën) door een cel via insluiting in een fagosoom.","definition":"<p><b>Fagocytose</b> is een vorm van endocytose waarbij een cel grote deeltjes omsluit, zoals bacteriën, celresten of stofdeeltjes.</p><p>Het gevormde fagosoom versmelt met een lysosoom, waarna de inhoud wordt verteerd. Neutrofielen en macrofagen zijn de belangrijkste fagocyten.</p>","image_url":"","wiki_title":"Phagocytosis","match":"fagocytose"},"apoptose":{"title":"Apoptose","short":"Geprogrammeerde celdood: een geordend 'zelfmoordprogramma' dat de cel netjes opruimt zonder ontsteking.","definition":"<p><b>Apoptose</b> is gecontroleerde celdood. De cel krimpt, het DNA wordt in stukken geknipt en de cel valt uiteen in nette blaasjes (apoptotic bodies).</p><p>Macrofagen ruimen die op zonder ontstekingsreactie. Het is essentieel voor ontwikkeling en het verwijderen van beschadigde cellen.</p>","image_url":"","wiki_title":"Apoptosis","match":"apoptose"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"glycolyse":{"title":"Glycolyse","short":"Afbraak van glucose tot pyruvaat in het cytoplasma, met een kleine netto-opbrengst aan ATP en NADH.","definition":"<p><b>Glycolyse</b> splitst in het cytoplasma één glucose in tien stappen tot twee moleculen pyruvaat.</p><p>Het levert netto 2 ATP en 2 NADH op en verloopt zonder zuurstof. Bij aanwezigheid van zuurstof gaat pyruvaat de citroenzuurcyclus in.</p>","image_url":"","wiki_title":"Glycolysis","match":"glycolyse"},"oxidatieve fosforylering":{"title":"Oxidatieve fosforylering","short":"Vorming van het grootste deel van de ATP via de elektronentransportketen en ATP-synthase in het mitochondrion.","definition":"<p>Bij <b>oxidatieve fosforylering</b> drijft de protongradiënt van de elektronentransportketen het enzym ATP-synthase aan.</p><p>Zo wordt uit ADP en fosfaat ATP gevormd — de belangrijkste ATP-bron van de cel, waarvoor zuurstof nodig is.</p>","image_url":"","wiki_title":"Oxidative phosphorylation","match":"oxidatieve fosforylering"},"fosforylering":{"title":"Fosforylering","short":"Toevoeging van een fosfaatgroep aan een eiwit; een veelgebruikte aan/uit-schakelaar van eiwitactiviteit.","definition":"<p><b>Fosforylering</b> is het koppelen van een fosfaatgroep aan een eiwit door een kinase. Een fosfatase haalt hem er weer af.</p><p>Zo schakelen cellen eiwitten razendsnel aan of uit — de basis van veel signaaltransductie.</p>","image_url":"","wiki_title":"Phosphorylation","match":"fosforylering|fosforylatie"},"keratinocyt":{"title":"Keratinocyt","short":"De hoofdcel van de epidermis; produceert keratine en bouwt al opschuivend de huidbarrière op.","definition":"<p>De <b>keratinocyt</b> maakt ongeveer 90% van de epidermiscellen uit. Vanuit het stratum basale schuift hij omhoog terwijl hij steeds meer keratine vormt.</p><p>Bovenaan aangekomen is hij een dode, verhoornde cel die de barrière vormt en uiteindelijk afschilfert.</p>","image_url":"","wiki_title":"Keratinocyte","match":"keratinocyt|keratinocyten"},"melanocyt":{"title":"Melanocyt","short":"Pigmentcel in het stratum basale die melanine maakt en dit aan omliggende keratinocyten afgeeft.","definition":"<p>De <b>melanocyt</b> ligt in het stratum basale en produceert in melanosomen het pigment melanine.</p><p>Via uitlopers geeft hij melanine af aan naburige keratinocyten, die er hun kern mee tegen UV-schade beschermen. Verschillen in huidskleur berusten op de activiteit, niet het aantal, van melanocyten.</p>","image_url":"","wiki_title":"Melanocyte","match":"melanocyt|melanocyten"},"neutrofiele granulocyt":{"title":"Neutrofiele granulocyt","short":"Meest voorkomende witte bloedcel en eerste verdedigingslinie tegen bacteriën via fagocytose.","definition":"<p>De <b>neutrofiele granulocyt</b> is de talrijkste leukocyt, met een gelobde kern, en als eerste ter plaatse bij een bacteriële infectie.</p><p>Hij ruimt bacteriën op door fagocytose en enzymen; dode neutrofielen vormen samen met bacterieresten de pus.</p>","image_url":"","wiki_title":"Neutrophil","match":"neutrofiele granulocyt|neutrofiele granulocyten"},"monocyt":{"title":"Monocyt","short":"Grootste witte bloedcel; verlaat het bloed en rijpt in de weefsels uit tot macrofaag of dendritische cel.","definition":"<p>De <b>monocyt</b> is de grootste circulerende leukocyt, met een niervormige kern. Hij circuleert enkele dagen en migreert dan de weefsels in.</p><p>Daar differentieert hij tot macrofaag of dendritische cel, die pathogenen fagocyteren en antigenen presenteren.</p>","image_url":"","wiki_title":"Monocyte","match":"monocyt|monocyten"},"macrofaag":{"title":"Macrofaag","short":"Grote fagocyt in de weefsels die pathogenen en celresten opruimt en antigenen presenteert.","definition":"<p>De <b>macrofaag</b> ontstaat uit een monocyt die het weefsel is binnengegaan. Hij fagocyteert bacteriën, dode cellen en afval.</p><p>Als antigeenpresenterende cel activeert hij ook T-cellen en scheidt hij ontstekingsmediatoren uit. In de huid heten verwante cellen histiocyten.</p>","image_url":"","wiki_title":"Macrophage","match":"macrofaag|macrofagen"},"lymfocyt":{"title":"Lymfocyt","short":"Witte bloedcel van de specifieke afweer; omvat de B-cellen (antistoffen) en T-cellen.","definition":"<p>De <b>lymfocyt</b> is de sleutelcel van het adaptieve (specifieke) immuunsysteem. B-lymfocyten maken antistoffen; T-lymfocyten doden geïnfecteerde cellen of sturen de afweer aan.</p><p>Lymfocyten circuleren tussen bloed, lymfe en lymfoïde organen.</p>","image_url":"","wiki_title":"Lymphocyte","match":"lymfocyt|lymfocyten"},"plasmacel":{"title":"Plasmacel","short":"Uit een B-cel gerijpte cel die grote hoeveelheden antistoffen (antilichamen) produceert.","definition":"<p>De <b>plasmacel</b> is een geactiveerde, uitgerijpte B-lymfocyt. Zijn sterk ontwikkelde ruw endoplasmatisch reticulum maakt hem tot een antistoffabriek.</p><p>Hij scheidt grote hoeveelheden specifieke antilichamen af tegen één antigeen.</p>","image_url":"","wiki_title":"Plasma cell","match":"plasmacel|plasmacellen"},"milt":{"title":"Milt","short":"Lymfoïd orgaan dat oude bloedcellen afbreekt en bloedgedragen ziekteverwekkers filtert.","definition":"<p>De <b>milt</b> filtert het bloed: de rode pulpa ruimt versleten erytrocyten op, de witte pulpa herbergt lymfocyten voor de afweer tegen bloedgedragen pathogenen.</p><p>Ook dient de milt als bloedreservoir.</p>","image_url":"","wiki_title":"Spleen","match":"milt"},"beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"beenmerg|het beenmerg"},"lymfeklier":{"title":"Lymfeklier","short":"Filterstation in de lymfebaan waar antigenen worden gepresenteerd en de afweerreactie op gang komt.","definition":"<p>De <b>lymfeklier</b> filtert de lymfe en is een ontmoetingsplaats voor antigeenpresenterende cellen en lymfocyten.</p><p>Hier worden T- en B-cellen geactiveerd; bij infectie zwellen lymfeklieren op doordat de lymfocyten zich vermenigvuldigen.</p>","image_url":"","wiki_title":"Lymph node","match":"lymfeklier|lymfeklieren|lymfklier|lymfklieren"},"elastine":{"title":"Elastine","short":"Rekbaar bindweefseleiwit dat huid, longen en bloedvaten na uitrekking hun vorm laat hervinden.","definition":"<p><b>Elastine</b> vormt elastische vezels die kunnen uitrekken en daarna weer terugveren.</p><p>Het geeft de huid, longen en slagaderwanden hun elasticiteit. Afname van elastine draagt bij aan huidveroudering en rimpels.</p>","image_url":"","wiki_title":"Elastin","match":"elastine"},"papula":{"title":"Papula","short":"Klein, vast, verheven en voelbaar huidknobbeltje (< ~1 cm).","definition":"<p>Een <b>papula</b> (papel) is een klein, stevig, verheven bultje kleiner dan ongeveer 1 cm dat je kunt voelen.</p><p>Voorbeelden zijn een insectenbeet-reactie of de bultjes bij acne. Meerdere versmolten papels vormen een plaque.</p>","image_url":"","wiki_title":"Papule","match":"papula|papel|papels|papula's|papula’s|papels"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"vesikel":{"title":"Vesikel","short":"Klein, met helder vocht gevuld blaasje in de huid (< ~1 cm).","definition":"<p>Een <b>vesikel</b> (vesicula) is een klein blaasje gevuld met helder vocht, kleiner dan ongeveer 1 cm.</p><p>Vesikels komen voor bij o.a. herpes, waterpokken en acuut eczeem. Een groter blaasje heet een bulla.</p>","image_url":"","wiki_title":"Blister","match":"vesikel|vesikels|vesicula|vesiculae"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"basaalcelcarcinoom":{"title":"Basaalcelcarcinoom","short":"Meest voorkomende, langzaam groeiende huidkanker die vrijwel nooit uitzaait.","definition":"<p>Het <b>basaalcelcarcinoom</b> is de meest voorkomende vorm van huidkanker, uitgaand van de basale keratinocyten. Het groeit langzaam en zaait vrijwel nooit uit, maar kan lokaal in de diepte woekeren.</p><p>Typisch is een glanzend, huidkleurig knobbeltje met teleangiëctasieën, vaak in het gezicht na jarenlange zonschade.</p>","image_url":"","wiki_title":"Basal-cell carcinoma","match":"basaalcelcarcinoom|basaalcel carcinoom|basaalcelcarinoom|basaalcarcinoom"},"plaveiselcelcarcinoom":{"title":"Plaveiselcelcarcinoom","short":"Op één na meest voorkomende huidkanker, uit keratinocyten; kan uitzaaien.","definition":"<p>Het <b>plaveiselcelcarcinoom</b> gaat uit van de keratinocyten van de epidermis en is de op één na meest voorkomende huidkanker.</p><p>Anders dan het basaalcelcarcinoom kan het metastaseren. Het ontstaat vooral op zonbeschadigde huid, vaak vanuit een actinische keratose.</p>","image_url":"","wiki_title":"Squamous-cell carcinoma","match":"plaveiselcelcarcinoom|plaveiselcel carcinoom"},"melanoom":{"title":"Melanoom","short":"Kwaadaardige tumor van melanocyten; relatief zeldzaam maar het gevaarlijkst door vroege uitzaaiing.","definition":"<p>Het <b>melanoom</b> is een kwaadaardige tumor van de pigmentcellen (melanocyten).</p><p>Het is de dodelijkste huidkanker omdat het vroeg kan uitzaaien. De ABCDE-regel (Asymmetrie, Begrenzing, Kleur, Diameter, Evolutie) helpt bij herkenning; de Breslowdikte bepaalt de prognose.</p>","image_url":"","wiki_title":"Melanoma","match":"melanoom|melanomen"},"actinische keratose":{"title":"Actinische keratose","short":"Ruw, schilferend plekje door chronische zonschade; een voorstadium van plaveiselcelcarcinoom.","definition":"<p>Een <b>actinische keratose</b> (keratosis actinica, zonlichtkeratose) is een ruwe, schilferende plek op chronisch aan de zon blootgestelde huid.</p><p>Het is een premaligne afwijking die kan overgaan in een plaveiselcelcarcinoom.</p>","image_url":"","wiki_title":"Actinic keratosis","match":"actinische keratose|keratosis actinica|zonlichtkeratose"},"excisie":{"title":"Excisie","short":"Chirurgisch wegsnijden van een huidafwijking, meestal met een marge gezond weefsel.","definition":"<p>Een <b>excisie</b> is het operatief wegsnijden van een laesie, doorgaans met een randje gezonde huid (marge).</p><p>Bij een diagnostische excisie wordt de hele afwijking verwijderd voor onderzoek; bij huidkanker is de marge afhankelijk van het type en de dikte.</p>","image_url":"","wiki_title":"Wide local excision","match":"excisie|diagnostische excisie"},"radiotherapie":{"title":"Radiotherapie","short":"Behandeling met ioniserende straling die het DNA van tumorcellen beschadigt.","definition":"<p><b>Radiotherapie</b> (bestraling) gebruikt ioniserende straling om het DNA van kankercellen zodanig te beschadigen dat ze afsterven.</p><p>In de dermatologie is het een alternatief voor chirurgie bij bijvoorbeeld basaal- en plaveiselcelcarcinomen, vooral bij oudere patiënten of moeilijke locaties.</p>","image_url":"","wiki_title":"Radiation therapy","match":"radiotherapie"},"autosomaal dominant":{"title":"Autosomaal dominant","short":"Overervingspatroon waarbij één afwijkend gen (op een niet-geslachtschromosoom) al ziekte geeft.","definition":"<p>Bij <b>autosomaal dominante</b> overerving volstaat één gemuteerd allel op een autosoom om de aandoening tot uiting te laten komen.</p><p>Aangedane ouders geven het gemiddeld aan de helft van hun kinderen door; de aandoening komt in elke generatie voor, ongeacht geslacht.</p>","image_url":"","wiki_title":"Dominance (genetics)","match":"autosomaal dominant"},"puntmutatie":{"title":"Puntmutatie","short":"Verandering van één enkele DNA-base.","definition":"<p>Een <b>puntmutatie</b> is de vervanging, invoeging of verwijdering van één enkele base in het DNA.</p><p>Afhankelijk van het effect op het codon spreekt men van een stille, missense of nonsense mutatie.</p>","image_url":"","wiki_title":"Point mutation","match":"puntmutatie"},"mrna":{"title":"mRNA","short":"Boodschapper-RNA dat de genetische code van het DNA naar de ribosomen brengt voor eiwitsynthese.","definition":"<p><b>mRNA</b> (messenger RNA) is de kopie van een gen die tijdens transcriptie in de kern wordt gemaakt.</p><p>Het reist naar het cytoplasma, waar ribosomen de codons aflezen om er een eiwit van te maken (translatie).</p>","image_url":"","wiki_title":"Messenger RNA","match":"mrna|messenger rna|boodschapper-rna"},"rrna":{"title":"rRNA","short":"Ribosomaal RNA: het bouw- en werkbestanddeel van de ribosomen.","definition":"<p><b>rRNA</b> (ribosomaal RNA) vormt samen met eiwitten de ribosomen.</p><p>Het is niet alleen structuur, maar katalyseert ook de peptidebinding tussen aminozuren — een ribozym-functie.</p>","image_url":"","wiki_title":"Ribosomal RNA","match":"rrna|ribosomaal rna"},"mirna":{"title":"miRNA","short":"Klein niet-coderend RNA dat de expressie van genen remt door aan mRNA te binden.","definition":"<p><b>miRNA</b> (microRNA) is een kort, niet-coderend RNA dat bindt aan complementair mRNA.</p><p>Daardoor wordt dat mRNA afgebroken of niet vertaald — een fijnregeling van de genexpressie.</p>","image_url":"","wiki_title":"MicroRNA","match":"mirna|microrna"},"cytomegalovirus":{"title":"Cytomegalovirus (CMV)","short":"CMV is een herpesvirus dat bij gezonden mild verloopt, maar gevaarlijk is bij immuungecompromitteerden en de belangrijkste congenitale virale infectie is.","definition":"<p>Het <strong>cytomegalovirus</strong> is een herpesvirus (HHV-5) dat na infectie levenslang latent aanwezig blijft. Geïnfecteerde cellen worden groot met kenmerkende ‘uilenoog’-inclusies.</p><p>Bij gezonde mensen verloopt infectie meestal ongemerkt of als een mononucleosebeeld. Bij transplantatie- en hiv-patiënten kan CMV retinitis, pneumonie en colitis veroorzaken. Congenitale CMV is de belangrijkste infectieuze oorzaak van aangeboren doofheid en ontwikkelingsachterstand.</p>","image_url":"","wiki_title":"Cytomegalovirus","match":"cytomegalovirus|cmv","option_only":true},"malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malaria|plasmodium|plasmodium falciparum","option_only":true},"tuberculose":{"title":"Tuberculose","short":"Tuberculose is een infectie met Mycobacterium tuberculosis, meestal in de longen, met langdurig hoesten, nachtzweten, gewichtsverlies en granulomen.","definition":"<p><strong>Tuberculose</strong> wordt veroorzaakt door <em>Mycobacterium tuberculosis</em> en verspreidt zich via aerosolen. Na infectie wordt de bacterie meestal ingekapseld in granulomen (latente tbc); bij verminderde afweer kan actieve ziekte ontstaan.</p><p>Longtuberculose geeft langdurig hoesten (soms met bloed), koorts, nachtzweten en gewichtsverlies; typisch zijn holtevorming in de longtoppen en granulomen met centrale <em>verkazing</em>. Behandeling met een combinatie van tuberculostatica gedurende minstens 6 maanden.</p>","image_url":"","wiki_title":"Tuberculosis","match":"tuberculose|tbc|tb","option_only":true},"chemotherapie":{"title":"Chemotherapie","short":"Chemotherapie is behandeling met cytostatica: medicijnen die snel delende (kanker)cellen doden of hun deling remmen.","definition":"<p><strong>Chemotherapie</strong> is behandeling met <em>cytostatica</em>. Deze grijpen in op de celdeling, bijvoorbeeld door DNA te beschadigen (alkylerende middelen, platinaverbindingen), de DNA-synthese te remmen (antimetabolieten) of de mitosespoel te verstoren (taxanen, vinca-alkaloïden).</p><p>Omdat ook gezonde, snel delende cellen geraakt worden, zijn bijwerkingen beenmergsuppressie, haaruitval, mucositis en misselijkheid. Chemotherapie kan curatief, (neo)adjuvant of palliatief worden ingezet.</p>","image_url":"","wiki_title":"Chemotherapy","match":"chemotherapie|chemo|cytostatica","option_only":true},"alcohol":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcohol|ethanol|alcoholgebruik|overmatig alcoholgebruik|alcoholmisbruik","option_only":true},"roken":{"title":"Roken","short":"Roken is de belangrijkste vermijdbare oorzaak van ziekte en sterfte: het veroorzaakt o.a. longkanker, COPD en hart- en vaatziekten.","definition":"<p>Tabaksrook bevat nicotine (verslavend), koolmonoxide, teer en tientallen kankerverwekkende stoffen. <strong>Roken</strong> beschadigt het luchtwegepitheel en het endotheel en bevordert ontsteking en trombose.</p><p>Het is een hoofdoorzaak van longkanker en andere kankers (o.a. mond, slokdarm, blaas), COPD, atherosclerose (myocardinfarct, CVA, perifeer arterieel vaatlijden) en complicaties in de zwangerschap. Stoppen loont op elke leeftijd.</p>","image_url":"","wiki_title":"Tobacco smoking","match":"roken|tabaksgebruik|tabak","option_only":true},"longfibrose":{"title":"Longfibrose","short":"Bij longfibrose wordt het longinterstitium vervangen door bindweefsel; de long wordt stug, met een restrictief beeld en verminderde diffusie.","definition":"<p>Bij <strong>longfibrose</strong> leidt beschadiging en abnormaal herstel van het longinterstitium tot verlittekening. Oorzaken zijn idiopathisch (IPF), stofblootstelling (asbest, silica), auto-immuunziekten, medicatie, bestraling of chronische extrinsieke allergische alveolitis.</p><p>De long wordt stijver (lagere compliantie): een <em>restrictieve</em> longfunctiestoornis (lage TLC en VC, normale of verhoogde FEV1/FVC) met verlaagde diffusiecapaciteit. Klachten: progressieve kortademigheid en droge hoest; bij auscultatie fijne ‘knisper’crepitaties; vaak trommelstokvingers.</p>","image_url":"","wiki_title":"Pulmonary fibrosis","match":"longfibrose|pulmonale fibrose|idiopathische pulmonale fibrose|ipf","option_only":true},"echo abdomen":{"title":"Echo abdomen","short":"Een echo abdomen is een echografisch onderzoek van de buikorganen; zonder straling en goed voor galblaas, galwegen, lever, nieren en vrij vocht.","definition":"<p>Bij een <strong>echo abdomen</strong> wordt met geluidsgolven een beeld gemaakt van de buikorganen. Het onderzoek gebruikt geen ioniserende straling, is goedkoop en direct beschikbaar.</p><p>Het is bijzonder geschikt voor het aantonen van galstenen en cholecystitis, verwijde galwegen, leverafwijkingen, nierstuwing (hydronefrose), een abdominaal aorta-aneurysma en vrij vocht. Darmgas en een dikke buikwand beperken het zicht; de kwaliteit hangt af van de onderzoeker.</p>","image_url":"","wiki_title":"Abdominal ultrasonography","match":"echo abdomen|echografie abdomen|echo van de buik|abdominale echografie|echo-abdomen","option_only":true},"ct abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct abdomen|ct-abdomen|ct van de buik|ct-scan abdomen","option_only":true},"auto-immuun hemolytische anemie":{"title":"Auto-immuun hemolytische anemie","short":"Bij AIHA maakt het lichaam antistoffen tegen de eigen rode bloedcellen, die daardoor worden afgebroken; de directe antiglobulinetest (Coombs) is positief.","definition":"<p>Bij <strong>auto-immuun hemolytische anemie</strong> binden auto-antistoffen aan erytrocyten, die vervolgens vooral in de milt worden afgebroken (type II-overgevoeligheid). Bij <em>warme</em> AIHA gaat het om IgG; bij <em>koude</em> AIHA om IgM met complementactivatie.</p><p>Laboratorium: anemie met verhoogde reticulocyten, verhoogd LDH en ongeconjugeerd bilirubine, verlaagd haptoglobine, sferocyten en een positieve directe antiglobulinetest (Coombs). Oorzaken: idiopathisch, lymfoproliferatieve ziekten, SLE, infecties (Mycoplasma, EBV) of geneesmiddelen.</p>","image_url":"","wiki_title":"Autoimmune hemolytic anemia","match":"auto-immuun hemolytische anemie|aiha|autoimmuun hemolytische anemie|auto-immuunhemolytische anemie","option_only":true},"maagcarcinoom":{"title":"Maagcarcinoom","short":"Een maagcarcinoom is een kwaadaardige tumor (meestal adenocarcinoom) van de maag; risicofactoren zijn o.a. H. pylori, roken en zoutrijke voeding.","definition":"<p>Het <strong>maagcarcinoom</strong> is meestal een adenocarcinoom, uitgaand van het klierepitheel. Het intestinale type ontstaat via een reeks van chronische (H. pylori-)gastritis, atrofie, intestinale metaplasie en dysplasie; het diffuse type (zegelringcellen) infiltreert de wand zonder duidelijke massa (linitis plastica).</p><p>Klachten komen vaak laat: verminderde eetlust, vroege verzadiging, gewichtsverlies, epigastrische pijn, anemie of slikklachten. Metastasen kunnen zich manifesteren als een klier van Virchow (links supraclaviculair) of ovariummetastasen (Krukenberg).</p>","image_url":"","wiki_title":"Stomach cancer","match":"maagcarcinoom|maagkanker|adenocarcinoom van de maag","option_only":true},"anemie":{"title":"Anemie","short":"Anemie is een te laag hemoglobinegehalte in het bloed, waardoor het zuurstoftransport vermindert.","definition":"<p>Bij <strong>anemie</strong> is de hemoglobineconcentratie verlaagd (bij volwassenen ongeveer &lt;8,5 mmol/L bij mannen en &lt;7,5 mmol/L bij vrouwen). Klachten: moeheid, kortademigheid bij inspanning, bleekheid en hartkloppingen.</p><p>Indeling op het MCV: <em>microcytair</em> (o.a. ijzergebrek, thalassemie), <em>normocytair</em> (o.a. acuut bloedverlies, chronische ziekte, nierfalen) en <em>macrocytair</em> (o.a. vitamine B12- of foliumzuurtekort). Daarnaast onderscheidt men verminderde aanmaak van versterkte afbraak (hemolyse) of verlies.</p>","image_url":"","wiki_title":"Anemia","match":"anemie|bloedarmoede","option_only":true},"koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"koorts|febris|pyrexie|hoge koorts","option_only":true},"maag":{"title":"Maag","short":"De maag slaat voedsel tijdelijk op, mengt het met maagzuur en pepsine en geeft het geleidelijk af aan het duodenum.","definition":"<p>De <strong>maag</strong> bestaat uit cardia, fundus, corpus, antrum en pylorus. Het slijmvlies bevat klieren met <em>pariëtale cellen</em> (zoutzuur en intrinsieke factor), <em>hoofdcellen</em> (pepsinogeen), slijmcellen en endocriene cellen (o.a. G-cellen met gastrine in het antrum).</p><p>De maag doodt micro-organismen, start de eiwitvertering en mengt voedsel tot chymus. Intrinsieke factor is nodig voor opname van vitamine B12 in het terminale ileum.</p>","image_url":"","wiki_title":"Stomach","match":"maag|gaster|ventriculus","option_only":true},"de milt":{"title":"Milt","short":"De milt filtert het bloed: hij ruimt oude en beschadigde rode bloedcellen op en vormt een afweerorgaan tegen bacteriën in het bloed.","definition":"<p>De <strong>milt</strong> ligt linksboven in de buik onder het diafragma. Ze bestaat uit <em>rode pulpa</em> (sinusoïden waar verouderde of afwijkende erytrocyten worden afgebroken) en <em>witte pulpa</em> (lymfatisch weefsel met B- en T-cellen rond arteriolen).</p><p>De milt is belangrijk voor de afweer tegen <em>gekapselde bacteriën</em> (pneumokok, meningokok, H. influenzae). Na splenectomie is het risico op een ernstige sepsis daardoor verhoogd; deze patiënten worden gevaccineerd.</p>","image_url":"","wiki_title":"Spleen","match":"de milt|milt|lien|splenomegalie","option_only":true},"myeloïde voorlopercellen":{"title":"Myeloïde voorlopercellen","short":"Myeloïde voorlopercellen zijn beenmergcellen waaruit erytrocyten, trombocyten, granulocyten en monocyten ontstaan.","definition":"<p>De hematopoëtische stamcel splitst zich in een <em>lymfoïde</em> en een <strong>myeloïde</strong> lijn. Uit de myeloïde voorlopercel (CMP) ontstaan via verdere tussenstappen de <em>erytrocyten</em>, <em>megakaryocyten</em> (bloedplaatjes), <em>granulocyten</em> (neutrofielen, eosinofielen, basofielen), <em>monocyten</em>/macrofagen en mestcellen.</p><p>Uit de lymfoïde lijn ontstaan B-cellen, T-cellen en NK-cellen.</p>","image_url":"","wiki_title":"Common myeloid progenitor","match":"myeloïde voorlopercellen|myeloïde voorlopercel|myeloïde progenitor|myeloïde stamcel","option_only":true},"myeloïde blasten":{"title":"Myeloïde blasten","short":"Myeloïde blasten zijn onrijpe voorlopercellen van de myeloïde reeks; een sterk verhoogd aantal in beenmerg of bloed past bij acute myeloïde leukemie (AML).","definition":"<p><strong>Myeloblasten</strong> zijn de vroegst herkenbare voorlopers van de granulocyten. Normaal vormen ze minder dan 5% van de cellen in het beenmerg en komen ze niet in het bloed voor.</p><p>Bij <em>acute myeloïde leukemie</em> stapelen onrijpe myeloïde blasten zich op (≥20% in het beenmerg), wat de normale aanmaak verdringt: anemie, trombocytopenie en infecties. Ze kunnen <em>Auerstaafjes</em> bevatten en zijn vaak positief voor myeloperoxidase.</p>","image_url":"","wiki_title":"Myeloblast","match":"myeloïde blasten|myeloblasten|myeloblast","option_only":true},"lymfoïde blasten":{"title":"Lymfoïde blasten","short":"Lymfoïde blasten (lymfoblasten) zijn onrijpe voorlopers van B- of T-lymfocyten; opstapeling past bij acute lymfatische leukemie (ALL).","definition":"<p><strong>Lymfoblasten</strong> zijn onrijpe cellen van de lymfoïde reeks waaruit B- en T-lymfocyten ontstaan.</p><p>Bij <em>acute lymfatische leukemie</em>, de meest voorkomende kinderkanker, stapelen ze zich op in beenmerg en bloed. Ze zijn klein met weinig cytoplasma, bevatten geen Auerstaafjes en zijn myeloperoxidase-negatief; ze zijn vaak TdT-positief. Typering via flowcytometrie (B- of T-cel-markers).</p>","image_url":"","wiki_title":"Lymphoblast","match":"lymfoïde blasten|lymfoblasten|lymfoblast","option_only":true},"depressieve stoornis":{"title":"Depressieve stoornis","short":"Een depressieve stoornis kenmerkt zich door minstens twee weken een sombere stemming en/of verlies van interesse en plezier, met o.a. slaap-, eetlust- en concentratieproblemen.","definition":"<p>Voor een <strong>depressieve stoornis</strong> (DSM-5) moeten gedurende minstens twee weken vijf of meer symptomen aanwezig zijn, waaronder ten minste één kernsymptoom: <em>depressieve stemming</em> of <em>verlies van interesse of plezier</em> (anhedonie).</p><p>Andere symptomen: veranderde eetlust of gewicht, slapeloosheid of juist veel slapen, psychomotorische remming of agitatie, vermoeidheid, schuldgevoelens of waardeloosheid, concentratieproblemen en gedachten aan de dood. Behandeling met psychotherapie en/of antidepressiva.</p>","image_url":"","wiki_title":"Major depressive disorder","match":"depressieve stoornis|depressie|depressieve episode|majeure depressie","option_only":true},"duodenum":{"title":"Duodenum (twaalfvingerige darm)","short":"Het duodenum is het eerste, C-vormige deel van de dunne darm; hier komen gal en pancreassap bij de voedselbrij.","definition":"<p>Het <strong>duodenum</strong> loopt van de pylorus in een C-bocht om de pancreaskop heen en gaat bij de flexura duodenojejunalis over in het jejunum. Het ligt grotendeels retroperitoneaal. In de pars descendens mondt via de papil van Vater de ductus choledochus samen met de ductus pancreaticus uit. Klieren van Brunner in de submucosa maken bicarbonaatrijk slijm dat het zure chymus neutraliseert; endocriene cellen maken o.a. secretine en cholecystokinine.</p>","image_url":"","wiki_title":"Duodenum","match":"duodenum|twaalfvingerige darm","option_only":true},"colon":{"title":"Colon (dikke darm)","short":"Het colon is de dikke darm van caecum tot rectum; het resorbeert water en zouten en dikt de ontlasting in.","definition":"<p>Het <strong>colon</strong> bestaat uit caecum, colon ascendens, transversum, descendens en sigmoideum, gevolgd door het rectum. Kenmerkend zijn taeniae coli, haustra en appendices epiploicae. Het slijmvlies heeft geen villi maar wel diepe crypten met veel slijmbekercellen. Het colon resorbeert water en elektrolyten, en de darmflora fermenteert vezels tot korteketenvetzuren.</p>","image_url":"","wiki_title":"Large intestine","match":"colon|dikke darm|dikkedarm","option_only":true},"terminale ileum":{"title":"Terminale ileum","short":"Het terminale ileum is het laatste stuk van de dunne darm, waar vitamine B12 en galzouten worden opgenomen.","definition":"<p>Het <strong>terminale ileum</strong> is het eindstuk van het ileum vlak voor de ileocaecaalklep. Hier worden vitamine B12 (als complex met intrinsieke factor) en geconjugeerde galzouten actief opgenomen. Ziekte of resectie van dit deel, bijvoorbeeld bij de ziekte van Crohn, kan B12-tekort en galzuurdiarree geven.</p>","image_url":"","wiki_title":"Ileum","match":"terminale ileum|terminaal ileum","option_only":true},"calcium":{"title":"Calcium","short":"Calcium is nodig voor botten, spiercontractie, zenuwgeleiding en stolling; de bloedspiegel wordt geregeld door PTH, vitamine D en calcitonine.","definition":"<p>Het meeste <strong>calcium</strong> zit in botten als hydroxyapatiet. In het bloed is ongeveer de helft eiwitgebonden (vooral aan albumine) en de rest vrij geïoniseerd, de biologisch actieve vorm. Calcium is tweede boodschapper in cellen en essentieel voor spiercontractie, neurotransmitterafgifte en stolling. Afwijkingen geven bijv. tetanie (hypocalciëmie) of dorst, obstipatie en verwardheid (hypercalciëmie).</p>","image_url":"","wiki_title":"Calcium in biology","match":"calcium|ca2+|calciumion","option_only":true},"neuropathie":{"title":"Neuropathie","short":"Neuropathie is een aandoening van perifere zenuwen, met gevoelsstoornissen, krachtsverlies en/of verlaagde reflexen.","definition":"<p>Een <strong>neuropathie</strong> kan één zenuw treffen (mononeuropathie, bijv. carpaletunnelsyndroom), meerdere zenuwen asymmetrisch (mononeuritis multiplex) of symmetrisch veel zenuwen tegelijk (polyneuropathie, typisch beginnend in de voeten). Oorzaken zijn o.a. diabetes, alcohol, vitamine B12-tekort, medicatie (chemotherapie), auto-immuniteit en erfelijke aandoeningen.</p>","image_url":"","wiki_title":"Peripheral neuropathy","match":"neuropathie|perifere neuropathie","option_only":true},"epstein-barrvirus":{"title":"Epstein-Barrvirus (EBV)","short":"EBV is een herpesvirus dat B-cellen infecteert; het veroorzaakt de ziekte van Pfeiffer en is geassocieerd met enkele kankers.","definition":"<p>Het <strong>Epstein-Barrvirus</strong> wordt via speeksel overgedragen. Op jonge leeftijd verloopt infectie vaak ongemerkt; bij adolescenten geeft het vaak mononucleosis infectiosa. Het virus blijft levenslang latent in B-cellen. EBV is geassocieerd met o.a. het Burkittlymfoom, het nasofarynxcarcinoom, sommige Hodgkinlymfomen en posttransplantatie-lymfoproliferatieve ziekte.</p>","image_url":"","wiki_title":"Epstein–Barr virus","match":"epstein-barrvirus|epstein-barrvirus (ebv)|ebv|epstein-barr virus","option_only":true},"leishmaniasis":{"title":"Leishmaniasis","short":"Leishmaniasis is een parasitaire infectie door Leishmania, overgebracht door zandvliegen, met huidzweren of een ernstige viscerale vorm.","definition":"<p>Bij <strong>cutane leishmaniasis</strong> ontstaat op de plek van de beet een langzaam groeiende, pijnloze zweer. Bij <strong>viscerale leishmaniasis</strong> (kala-azar) infecteert de parasiet macrofagen in milt, lever en beenmerg, met koorts, sterke splenomegalie, pancytopenie en gewichtsverlies; onbehandeld is dit dodelijk. Komt voor rond de Middellandse Zee, Afrika, Azië en Zuid-Amerika.</p>","image_url":"","wiki_title":"Leishmaniasis","match":"leishmaniasis|leishmania","option_only":true},"dengue":{"title":"Dengue (knokkelkoorts)","short":"Dengue is een door Aedes-muggen overgebrachte virusinfectie met hoge koorts, hevige spier- en gewrichtspijn en huiduitslag.","definition":"<p><strong>Dengue</strong> wordt veroorzaakt door een flavivirus met vier serotypes. Na een paar dagen incubatie volgen hoge koorts, hoofdpijn achter de ogen, spier- en gewrichtspijn en een rash. Een tweede infectie met een ander serotype geeft een groter risico op ernstige dengue met plasmalekkage, bloedingen en shock (door antistof-afhankelijke versterking). Behandeling is ondersteunend; NSAID's worden vermeden.</p>","image_url":"","wiki_title":"Dengue fever","match":"dengue|knokkelkoorts|denguevirus","option_only":true},"pulmonale hypertensie":{"title":"Pulmonale hypertensie","short":"Pulmonale hypertensie is een verhoogde druk in de longslagaders, die op termijn rechtszijdig hartfalen veroorzaakt.","definition":"<p>Bij <strong>pulmonale hypertensie</strong> is de gemiddelde druk in de a. pulmonalis verhoogd (&gt;20 mmHg in rust bij hartkatheterisatie). Oorzaken: linkszijdige hartziekte (meest voorkomend), longziekten met hypoxie, chronische longembolieën, en zeldzamer pulmonale arteriële hypertensie. Klachten zijn kortademigheid en vermoeidheid bij inspanning; later ontstaan oedeem en tekenen van rechtsfalen.</p>","image_url":"","wiki_title":"Pulmonary hypertension","match":"pulmonale hypertensie","option_only":true},"longcarcinoom":{"title":"Longcarcinoom","short":"Longkanker is een kwaadaardige tumor uitgaande van het epitheel van de luchtwegen; roken is de belangrijkste oorzaak.","definition":"<p>Het <strong>longcarcinoom</strong> wordt ingedeeld in niet-kleincellig (o.a. adenocarcinoom en plaveiselcelcarcinoom) en kleincellig longcarcinoom. Klachten zijn o.a. aanhoudende hoest, hemoptoë, kortademigheid, gewichtsverlies en recidiverende pneumonieën; vaak wordt het pas laat ontdekt. Paraneoplastische syndromen (zoals SIADH, hypercalciëmie, Lambert-Eaton) komen voor.</p>","image_url":"","wiki_title":"Lung cancer","match":"longcarcinoom|longkanker|bronchuscarcinoom","option_only":true},"nierinsufficiëntie":{"title":"Nierinsufficiëntie (nierfalen)","short":"Bij nierinsufficiëntie schiet de nierfunctie tekort, met ophoping van afvalstoffen en verstoring van water-, zout- en zuurhuishouding.","definition":"<p><strong>Acuut nierfalen</strong> ontstaat binnen uren tot dagen en wordt ingedeeld in prerenaal (ondervulling), renaal (bijv. acute tubulusnecrose, glomerulonefritis) en postrenaal (obstructie). <strong>Chronische nierschade</strong> is een eGFR &lt; 60 of nierschade langer dan 3 maanden, meestal door diabetes en hypertensie. Gevolgen zijn o.a. hyperkaliëmie, metabole acidose, anemie (minder EPO), botziekte en hypertensie.</p>","image_url":"","wiki_title":"Kidney failure","match":"nierinsufficiëntie|nierfalen|nierinsufficientie|chronische nierschade","option_only":true},"oedeem":{"title":"Oedeem","short":"Oedeem is een ophoping van vocht in het interstitium, bijvoorbeeld als zwelling van enkels of onderbenen.","definition":"<p><strong>Oedeem</strong> ontstaat volgens de wetten van Starling door een verhoogde hydrostatische druk (hartfalen, veneuze insufficiëntie, overvulling), een verlaagde colloïd-osmotische druk (laag albumine bij nefrotisch syndroom, leverziekte, ondervoeding), een verhoogde vaatpermeabiliteit (ontsteking, allergie) of een verminderde lymfeafvoer (lymfoedeem). Putjesvormend oedeem blijft na indrukken even zichtbaar.</p>","image_url":"","wiki_title":"Edema","match":"oedeem|vochtophoping","option_only":true},"hypercalciëmie":{"title":"Hypercalciëmie","short":"Hypercalciëmie is een te hoog calcium in het bloed, meestal door primaire hyperparathyreoïdie of een maligniteit.","definition":"<p>Klachten van <strong>hypercalciëmie</strong> zijn samen te vatten als ‘stones, bones, groans and psychic moans’: nierstenen en polyurie, botpijn, obstipatie, misselijkheid en buikpijn, vermoeidheid en verwardheid; ook een verkort QT-interval. Bij maligniteit gaat het om PTHrP-productie, botmetastasen of (bij lymfomen) overmatig calcitriol. Behandeling: ruim vocht en bisfosfonaten.</p>","image_url":"","wiki_title":"Hypercalcaemia","match":"hypercalciëmie|hypercalciemie","option_only":true},"overgewicht":{"title":"Overgewicht","short":"Overgewicht is een te hoog lichaamsgewicht ten opzichte van de lengte, gedefinieerd als een BMI tussen 25 en 30 kg/m².","definition":"<p>Bij <strong>overgewicht</strong> (BMI 25–30) en vooral bij obesitas (BMI ≥30) neemt het risico op diabetes type 2, hart- en vaatziekten, artrose en sommige kankers toe. De verdeling van het vet is belangrijk: buikvet (gemeten met de middelomtrek) is metabool ongunstiger dan vet op heupen en bovenbenen.</p>","image_url":"","wiki_title":"Overweight","match":"overgewicht","option_only":true},"ileus":{"title":"Ileus","short":"Een ileus is een stilstand van de darmpassage, door een mechanische afsluiting of door verlamming van de darm.","definition":"<p>Bij een <strong>mechanische ileus</strong> is de darm afgesloten, bijvoorbeeld door verklevingen, een beklemde hernia, een tumor of een volvulus; er zijn koliekachtige buikpijn, braken, een opgezette buik en hoogklinkende peristaltiek. Bij een <strong>paralytische ileus</strong> (na operaties, bij peritonitis, elektrolytstoornissen of medicatie) staat de darm stil en is het stil bij auscultatie. Diagnose met X-buikoverzicht of CT.</p>","image_url":"","wiki_title":"Bowel obstruction","match":"ileus|darmafsluiting","option_only":true},"coloncarcinoom":{"title":"Coloncarcinoom (darmkanker)","short":"Coloncarcinoom is een kwaadaardige tumor van de dikke darm, meestal een adenocarcinoom dat ontstaat uit een poliep.","definition":"<p>Het <strong>colorectaal carcinoom</strong> ontstaat meestal via de adenoom-carcinoomsequentie, waarbij mutaties (o.a. in APC, KRAS, p53) zich opstapelen. Risicofactoren zijn leeftijd, familiaire belasting (FAP, Lynch-syndroom), IBD, rood en bewerkt vlees, alcohol en roken. Klachten: veranderd ontlastingspatroon, bloed bij de ontlasting en ijzergebreksanemie. In Nederland is er een bevolkingsonderzoek met de FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"coloncarcinoom|darmkanker|colorectaal carcinoom|dikkedarmkanker","option_only":true},"coeliakie":{"title":"Coeliakie","short":"Coeliakie is een auto-immuunziekte waarbij gluten een ontsteking van de dunne darm met vlokatrofie veroorzaken.","definition":"<p>Bij <strong>coeliakie</strong> (geassocieerd met HLA-DQ2/DQ8) wordt gliadine door weefseltransglutaminase gemodificeerd en daarna door T-cellen herkend, wat leidt tot vlokatrofie en crypthyperplasie. Klachten: diarree, buikpijn, gewichtsverlies, groeiachterstand, ijzergebrek en vermoeidheid, maar ook atypische presentaties. Diagnose met anti-tTG-antistoffen en een duodenumbiopt; behandeling is een levenslang glutenvrij dieet.</p>","image_url":"","wiki_title":"Coeliac disease","match":"coeliakie|glutenintolerantie|glutenenteropathie","option_only":true},"gastro-duodenoscopie":{"title":"Gastroduodenoscopie","short":"Bij een gastroduodenoscopie worden slokdarm, maag en duodenum met een flexibele endoscoop bekeken.","definition":"<p>Bij een <strong>gastroduodenoscopie</strong> gaat een flexibele scoop via de mond naar het duodenum. Er kunnen biopten worden genomen (bijv. voor coeliakie of H. pylori) en behandelingen worden uitgevoerd, zoals het stelpen van een bloeding of het oprekken van een stenose. Het onderzoek gebeurt met keelverdoving, eventueel met sedatie.</p>","image_url":"","wiki_title":"Esophagogastroduodenoscopy","match":"gastro-duodenoscopie|gastroduodenoscopie|gastroscopie","option_only":true},"coloscopie":{"title":"Coloscopie","short":"Bij een coloscopie wordt de hele dikke darm met een flexibele endoscoop bekeken, na darmvoorbereiding.","definition":"<p>Een <strong>coloscopie</strong> wordt gedaan bij o.a. bloed bij de ontlasting, een veranderd ontlastingspatroon, ijzergebreksanemie, een positieve FIT-test en voor surveillance bij poliepen of IBD. Poliepen kunnen direct worden verwijderd en er kunnen biopten worden genomen. Risico's zijn bloeding en (zelden) perforatie.</p>","image_url":"","wiki_title":"Colonoscopy","match":"coloscopie|colonoscopie","option_only":true},"myelocyten":{"title":"Myelocyten","short":"Myelocyten zijn tussenstadia in de rijping van granulocyten, na de promyelocyt; normaal komen ze alleen in het beenmerg voor.","definition":"<p>In een <strong>myelocyt</strong> verschijnen voor het eerst de specifieke korrels die bepalen of de cel een neutrofiel, eosinofiel of basofiel wordt. Het is het laatste stadium dat nog kan delen. Myelocyten in het perifere bloed (‘linksverschuiving’ of een leuko-erytroblastair beeld) passen bij ernstige infectie, chronische myeloïde leukemie of beenmerginfiltratie.</p>","image_url":"","wiki_title":"Myelocyte","match":"myelocyten|myelocyt","option_only":true},"trombopenie":{"title":"Trombocytopenie","short":"Trombocytopenie is een te laag aantal bloedplaatjes, met een verhoogde neiging tot bloedingen.","definition":"<p>Bij <strong>trombocytopenie</strong> (&lt;150 × 10⁹/L) ontstaan pas bij lage waarden (&lt;20–50) spontane huid- en slijmvliesbloedingen zoals petechiën en neusbloedingen. Oorzaken: verminderde aanmaak (beenmergziekte, chemotherapie, B12-tekort), versterkte afbraak (ITP, HIT, DIS, TTP), sequestratie in een vergrote milt of verdunning. Een pseudotrombopenie door klontering in EDTA-buizen moet worden uitgesloten.</p>","image_url":"","wiki_title":"Thrombocytopenia","match":"trombopenie|trombocytopenie","option_only":true},"ijzergebreksanemie":{"title":"IJzergebreksanemie","short":"IJzergebreksanemie is bloedarmoede door een tekort aan ijzer, met kleine, bleke rode bloedcellen.","definition":"<p><strong>IJzergebreksanemie</strong> geeft een microcytaire, hypochrome anemie met een laag ferritine. Oorzaken zijn bloedverlies (menstruatie, maag-darmkanaal), te weinig inname, verhoogde behoefte (groei, zwangerschap) of verminderde opname (coeliakie, maagresectie). Bij mannen en vrouwen na de menopauze moet een bron van bloedverlies in de tractus digestivus worden uitgesloten.</p>","image_url":"","wiki_title":"Iron-deficiency anemia","match":"ijzergebreksanemie|ijzergebrek","option_only":true},"hodgkin lymfoom":{"title":"Hodgkinlymfoom","short":"Het Hodgkinlymfoom is een kwaadaardige ziekte van het lymfeweefsel, gekenmerkt door Reed-Sternbergcellen.","definition":"<p>Het <strong>Hodgkinlymfoom</strong> komt vooral voor bij jongvolwassenen en ouderen. Het begint vaak met een pijnloze lymfeklierzwelling in de hals of het mediastinum en verspreidt zich via aangrenzende kliergroepen. B-symptomen (koorts, nachtzweten, gewichtsverlies) en jeuk komen voor. In het weefsel zijn grote Reed-Sternbergcellen (CD15+, CD30+) in een ontstekingsachtergrond te zien. De prognose is meestal goed.</p>","image_url":"","wiki_title":"Hodgkin lymphoma","match":"hodgkin lymfoom|hodgkinlymfoom|ziekte van hodgkin","option_only":true},"diffuus grootcellig b cel lymfoom":{"title":"Diffuus grootcellig B-cellymfoom","short":"Het diffuus grootcellig B-cellymfoom is een agressief non-Hodgkinlymfoom dat snel groeit maar vaak goed op behandeling reageert.","definition":"<p><strong>DLBCL</strong> is het meest voorkomende non-Hodgkinlymfoom. Het presenteert zich vaak met snel groeiende lymfeklieren of een tumor buiten de klieren (bijv. maag, hersenen), soms met B-symptomen. Microscopisch zijn er grote B-cellen in een diffuus groeipatroon. Behandeling met R-CHOP-chemotherapie kan een groot deel genezen.</p>","image_url":"","wiki_title":"Diffuse large B-cell lymphoma","match":"diffuus grootcellig b cel lymfoom|diffuus grootcellig b-cellymfoom|dlbcl","option_only":true},"chronische lymfatische leukemie":{"title":"Chronische lymfatische leukemie (CLL)","short":"CLL is een langzaam verlopende leukemie met ophoping van rijpe, maar disfunctionele B-lymfocyten, vooral bij ouderen.","definition":"<p>Bij <strong>CLL</strong> is er een lymfocytose met kleine rijpe B-cellen (CD5+, CD23+) en kenmerkende ‘Gumprecht-schaduwen’ in het uitstrijkje. Vaak wordt het toevallig ontdekt. Later kunnen lymfadenopathie, splenomegalie, anemie, trombopenie, hypogammaglobulinemie (infecties) en auto-immuuncytopenieën optreden. Behandeling pas bij actieve ziekte.</p>","image_url":"","wiki_title":"Chronic lymphocytic leukemia","match":"chronische lymfatische leukemie|cll","option_only":true},"nsaids":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"nsaids|nsaid|nsaid's|antiflogistica|ontstekingsremmers","option_only":true},"marchanderen":{"title":"Marchanderen (rouwfase)","short":"Marchanderen is een fase in het rouwmodel van Kübler-Ross waarin iemand probeert het onvermijdelijke uit te stellen door te ‘onderhandelen’.","definition":"<p>Kübler-Ross beschreef bij mensen met een dodelijke ziekte de fasen <strong>ontkenning, woede, marchanderen, depressie en aanvaarding</strong>. Bij marchanderen probeert iemand afspraken te maken (‘als ik maar de bruiloft van mijn dochter mag meemaken’). De fasen verlopen in de praktijk niet strikt na elkaar.</p>","image_url":"","wiki_title":"Five stages of grief","match":"marchanderen","option_only":true},"woede":{"title":"Woede (rouwfase)","short":"Woede is een fase in het rouwmodel van Kübler-Ross, waarin iemand boos is over het verlies of de ziekte.","definition":"<p>In het model van <strong>Kübler-Ross</strong> volgt woede vaak op ontkenning: ‘Waarom ik?’ De boosheid kan zich richten op naasten, God of de hulpverleners. Het is belangrijk die niet persoonlijk op te vatten en ruimte te geven aan de emotie.</p>","image_url":"","wiki_title":"Five stages of grief","match":"woede","option_only":true},"ontkenning":{"title":"Ontkenning (rouwfase)","short":"Ontkenning is een fase in het rouwmodel van Kübler-Ross en een afweermechanisme waarbij iemand een pijnlijke werkelijkheid niet toelaat.","definition":"<p><strong>Ontkenning</strong> beschermt tijdelijk tegen een overweldigende boodschap (‘Dit kan niet waar zijn’). Kübler-Ross beschreef het als eerste fase na slecht nieuws. Het kan helpen de schok op te vangen, maar langdurige ontkenning kan therapietrouw en besluitvorming in de weg staan.</p>","image_url":"","wiki_title":"Denial","match":"ontkenning","option_only":true},"morfine":{"title":"Morfine","short":"Morfine is een sterk werkend opioïd dat µ-opioïdreceptoren activeert; gebruikt bij ernstige pijn en kortademigheid in de palliatieve fase.","definition":"<p><strong>Morfine</strong> werkt pijnstillend via µ-receptoren in het centrale zenuwstelsel. Bijwerkingen zijn obstipatie (altijd een laxans erbij), misselijkheid, sufheid, ademhalingsdepressie, miosis en jeuk; bij langdurig gebruik ontstaan tolerantie en afhankelijkheid. De actieve metabolieten worden via de nier uitgescheiden en hopen op bij nierfalen. Antidotum: naloxon.</p>","image_url":"","wiki_title":"Morphine","match":"morfine|morphine","option_only":true},"mammacarcinoom":{"title":"Mammacarcinoom (borstkanker)","short":"Het mammacarcinoom is een kwaadaardige tumor van de borstklier, de meest voorkomende kanker bij vrouwen.","definition":"<p>Het <strong>mammacarcinoom</strong> is meestal een invasief carcinoom uitgaande van de afvoergangen (ductaal) of lobjes (lobulair). Risicofactoren zijn leeftijd, familiaire belasting (BRCA1/2), lange oestrogeenblootstelling en alcohol. Behandeling hangt af van stadium en receptorstatus (oestrogeen, progesteron, HER2): chirurgie, radiotherapie, hormonale therapie, chemotherapie en doelgerichte therapie. Er is een bevolkingsonderzoek met mammografie.</p>","image_url":"","wiki_title":"Breast cancer","match":"mammacarcinoom|borstkanker","option_only":true},"prostaatcarcinoom":{"title":"Prostaatcarcinoom","short":"Het prostaatcarcinoom is een kwaadaardige tumor van de prostaat, meestal een adenocarcinoom uitgaand van de perifere zone.","definition":"<p><strong>Prostaatkanker</strong> komt vooral voor bij oudere mannen en groeit vaak langzaam. Vroege stadia geven meestal geen klachten; gevorderde stadia kunnen plasklachten en botmetastasen (botpijn) geven. Diagnostiek met rectaal toucher, PSA, MRI en biopten (Gleason-score). Behandeling varieert van actief volgen tot operatie, radiotherapie en hormonale therapie.</p>","image_url":"","wiki_title":"Prostate cancer","match":"prostaatcarcinoom|prostaatkanker","option_only":true},"adenocarcinoom":{"title":"Adenocarcinoom","short":"Een adenocarcinoom is een kwaadaardige tumor van klierepitheel, zoals in darm, borst, prostaat, long en pancreas.","definition":"<p>Een <strong>adenocarcinoom</strong> vormt (verwaarloosde) klierstructuren of maakt slijm. Het is de meest voorkomende vorm van kanker van colon, maag, pancreas, prostaat, borst en een groot deel van het longcarcinoom. De mate van differentiatie (graad) en het stadium bepalen de prognose.</p>","image_url":"","wiki_title":"Adenocarcinoma","match":"adenocarcinoom|adenocarcinomen","option_only":true},"acute myeloïde leukemie":{"title":"Acute myeloïde leukemie (AML)","short":"AML is een agressieve kanker van het beenmerg waarbij onrijpe myeloïde voorlopercellen (blasten) zich ophopen.","definition":"<p>Bij <strong>AML</strong> verdringen myeloblasten (≥20% in het beenmerg) de normale bloedaanmaak, met anemie, trombocytopenie (bloedingen) en neutropenie (infecties). Het komt vooral bij ouderen voor. Blasten kunnen Auerstaafjes bevatten. Bij acute promyelocytenleukemie (t(15;17)) dreigt diffuse intravasale stolling; die vorm reageert goed op all-trans-retinoïnezuur. Behandeling met intensieve chemotherapie, eventueel stamceltransplantatie.</p>","image_url":"","wiki_title":"Acute myeloid leukemia","match":"acute myeloïde leukemie|aml|acute myeloide leukemie","option_only":true},"acute lymfatische leukemie":{"title":"Acute lymfatische leukemie (ALL)","short":"ALL is een kanker van onrijpe lymfoïde voorlopercellen; de meest voorkomende kinderkanker.","definition":"<p>Bij <strong>ALL</strong> hopen lymfoblasten zich op in beenmerg en bloed. Klachten ontstaan door beenmergfalen (bleekheid, bloedingen, infecties), botpijn en infiltratie van lymfeklieren, lever, milt, CZS of testes. De meeste gevallen zijn van B-celoorsprong. Bij kinderen is de genezingskans met chemotherapie hoog.</p>","image_url":"","wiki_title":"Acute lymphoblastic leukemia","match":"acute lymfatische leukemie|acute lymfoblastaire leukemie","option_only":true},"chronische myeloïde leukemie":{"title":"Chronische myeloïde leukemie (CML)","short":"CML is een myeloproliferatieve ziekte door het Philadelphiachromosoom (BCR-ABL), met een sterke toename van rijpe en rijpende granulocyten.","definition":"<p>Bij <strong>CML</strong> geeft de translocatie t(9;22) het fusiegen BCR-ABL, een permanent actief tyrosinekinase. Kenmerkend zijn een forse leukocytose met alle rijpingsstadia van de myeloïde reeks, basofilie en een vergrote milt. Tyrosinekinaseremmers zoals imatinib hebben de prognose sterk verbeterd. Zonder behandeling kan een blastencrisis ontstaan.</p>","image_url":"","wiki_title":"Chronic myelogenous leukemia","match":"chronische myeloïde leukemie|chronische myeloide leukemie|cml","option_only":true},"multipel myeloom":{"title":"Multipel myeloom (ziekte van Kahler)","short":"Het multipel myeloom is een kwaadaardige woekering van plasmacellen in het beenmerg, die een monoklonaal eiwit (M-proteïne) maken.","definition":"<p>Bij het <strong>multipel myeloom</strong> veroorzaken de plasmacellen botafbraak en beenmergverdringing. Klassieke kenmerken (CRAB): hypercalciëmie, nierfunctiestoornissen (o.a. door lichte ketens), anemie en botlaesies (‘punched-out’ op röntgenfoto's). Ook de BSE is sterk verhoogd en patiënten hebben een verhoogd infectierisico. Diagnostiek met eiwitspectrum, vrije lichte ketens en beenmergonderzoek.</p>","image_url":"","wiki_title":"Multiple myeloma","match":"multipel myeloom|ziekte van kahler|myeloom","option_only":true},"m-proteïne":{"title":"M-proteïne (paraproteïne)","short":"Een M-proteïne is een monoklonaal immunoglobuline of een lichte keten, gemaakt door één kloon van plasmacellen of B-cellen.","definition":"<p>Een <strong>M-proteïne</strong> is te zien als een smalle piek (M-piek) in het eiwitspectrum en wordt getypeerd met immunofixatie. Het komt voor bij MGUS (een voorstadium zonder klachten), het multipel myeloom, AL-amyloïdose en sommige lymfomen. Vrije lichte ketens in de urine heten Bence-Jones-eiwit.</p>","image_url":"","wiki_title":"Paraproteinemia","match":"m-proteïne|m-proteine|paraproteïne|monoklonaal eiwit","option_only":true},"burkitt lymfoom":{"title":"Burkittlymfoom","short":"Het Burkittlymfoom is een zeer snel groeiend B-cellymfoom met een translocatie van het MYC-gen.","definition":"<p>Het <strong>Burkittlymfoom</strong> heeft een t(8;14) waardoor MYC sterk tot expressie komt; vrijwel alle cellen delen. Microscopisch geeft dat een ‘sterrenhemel’-beeld (macrofagen tussen de tumorcellen). De endemische vorm (Afrika, kaak) is sterk geassocieerd met EBV en malaria; de sporadische vorm zit vaak in de buik. Door de snelle celdood kan bij behandeling een tumorlysissyndroom ontstaan.</p>","image_url":"","wiki_title":"Burkitt lymphoma","match":"burkitt lymfoom|burkittlymfoom","option_only":true},"non-hodgkin lymfoom":{"title":"Non-Hodgkinlymfoom","short":"Non-Hodgkinlymfomen zijn een grote groep kwaadaardige ziekten van B-, T- of NK-cellen, van indolent tot zeer agressief.","definition":"<p><strong>Non-Hodgkinlymfomen</strong> worden ingedeeld naar celtype en gedrag. Indolente vormen (bijv. folliculair lymfoom) groeien langzaam maar zijn vaak niet te genezen; agressieve vormen (bijv. diffuus grootcellig B-cellymfoom, Burkitt) groeien snel maar zijn vaak wel curabel. Klachten: pijnloze lymfeklierzwelling, B-symptomen en extranodale lokalisaties.</p>","image_url":"","wiki_title":"Non-Hodgkin lymphoma","match":"non-hodgkin lymfoom|non-hodgkinlymfoom|nhl","option_only":true},"folliculair non hodgkin lymfoom":{"title":"Folliculair lymfoom","short":"Het folliculair lymfoom is een langzaam groeiend B-cellymfoom met een t(14;18)-translocatie en overexpressie van BCL2.","definition":"<p>Het <strong>folliculair lymfoom</strong> komt vooral bij ouderen voor en geeft vaak gegeneraliseerde, pijnloze lymfeklierzwelling die jarenlang kan wisselen. Door BCL2-overexpressie ontsnappen de cellen aan apoptose. Het is meestal niet te genezen, maar heeft een lang beloop; behandeling vaak pas bij klachten. Het kan transformeren naar een agressief lymfoom.</p>","image_url":"","wiki_title":"Follicular lymphoma","match":"folliculair non hodgkin lymfoom|folliculair lymfoom","option_only":true},"aplastische anemie":{"title":"Aplastische anemie","short":"Bij aplastische anemie maakt het beenmerg te weinig bloedcellen van alle reeksen, door verlies van stamcellen.","definition":"<p>Bij <strong>aplastische anemie</strong> is het beenmerg leeg (hypocellulair, vervangen door vet), met pancytopenie: anemie, infecties en bloedingen. De oorzaak is meestal auto-immuun (T-cellen tegen stamcellen), soms medicatie, straling, virussen of een erfelijke ziekte (Fanconi). Behandeling met immunosuppressie of stamceltransplantatie.</p>","image_url":"","wiki_title":"Aplastic anemia","match":"aplastische anemie","option_only":true},"sferocytose":{"title":"Hereditaire sferocytose","short":"Hereditaire sferocytose is een erfelijk defect in het membraanskelet van rode bloedcellen, waardoor ze bolvormig worden en in de milt worden afgebroken.","definition":"<p>Bij <strong>hereditaire sferocytose</strong> (vaak een defect in spectrine of ankyrine) verliezen erytrocyten membraan en worden ze klein en rond, zonder centrale opheldering. Ze zijn minder vervormbaar en worden in de milt afgebroken: hemolytische anemie, icterus, galstenen en splenomegalie. Het MCHC is verhoogd. Splenectomie vermindert de hemolyse.</p>","image_url":"","wiki_title":"Hereditary spherocytosis","match":"sferocytose|hereditaire sferocytose","option_only":true},"sikkelcelziekte":{"title":"Sikkelcelziekte","short":"Sikkelcelziekte is een erfelijke hemoglobinopathie waarbij afwijkend hemoglobine (HbS) bij zuurstoftekort polymeriseert en rode bloedcellen sikkelvormig maakt.","definition":"<p>Bij <strong>sikkelcelziekte</strong> (homozygoot HbS, autosomaal recessief) verstoppen sikkelcellen kleine vaatjes en worden ze snel afgebroken. Gevolgen: pijncrises, hemolytische anemie, acute chest syndrome, herseninfarcten, miltinfarcten (functionele asplenie, infecties met gekapselde bacteriën) en priapisme. Dragerschap beschermt deels tegen malaria. Behandeling o.a. met hydroxycarbamide en transfusies.</p>","image_url":"","wiki_title":"Sickle cell disease","match":"sikkelcelziekte|sikkelcelanemie","option_only":true},"beenmergonderzoek":{"title":"Beenmergonderzoek","short":"Bij beenmergonderzoek wordt beenmerg uit de bekkenkam opgezogen en/of een biopt genomen om de bloedaanmaak te beoordelen.","definition":"<p>Een <strong>beenmergaspiraat</strong> geeft informatie over de celsoorten (cytologie, flowcytometrie, cytogenetica); een <strong>biopt</strong> over de cellulariteit en architectuur (bijv. fibrose, infiltratie). Het wordt gedaan bij onverklaarde cytopenieën, verdenking op leukemie, myeloom of lymfoom en voor stadiëring.</p>","image_url":"","wiki_title":"Bone marrow examination","match":"beenmergonderzoek|beenmergpunctie|beenmergbiopt","option_only":true},"rituximab":{"title":"Rituximab","short":"Rituximab is een monoklonaal antilichaam tegen CD20 op B-cellen; gebruikt bij lymfomen, CLL en auto-immuunziekten.","definition":"<p><strong>Rituximab</strong> bindt aan CD20 op rijpe B-cellen en vernietigt ze via complement en ADCC. Plasmacellen (CD20-negatief) blijven gespaard. Indicaties zijn B-cel-non-Hodgkinlymfomen, CLL, reumatoïde artritis en ANCA-vasculitis. Bijwerkingen: infusiereacties, infecties en reactivatie van hepatitis B.</p>","image_url":"","wiki_title":"Rituximab","match":"rituximab|anti-cd20","option_only":true},"dexamethason":{"title":"Dexamethason","short":"Dexamethason is een sterk en langwerkend glucocorticoïd zonder mineralocorticoïde werking.","definition":"<p><strong>Dexamethason</strong> is ongeveer 25–30 keer zo krachtig als cortisol. Het wordt gebruikt bij hersenoedeem rond tumoren, bacteriële meningitis (vóór of met antibiotica), misselijkheid door chemotherapie, ernstige COVID-19, en ter longrijping bij dreigende vroeggeboorte. Ook gebruikt bij de dexamethasonsuppressietest voor het syndroom van Cushing.</p>","image_url":"","wiki_title":"Dexamethasone","match":"dexamethason|dexamethasone","option_only":true},"microscopische hematurie":{"title":"Microscopische hematurie","short":"Bij microscopische hematurie zijn rode bloedcellen alleen met de microscoop of een teststrook in de urine aantoonbaar.","definition":"<p><strong>Hematurie</strong> kan glomerulair zijn (dysmorfe erytrocyten, erytrocytencilinders, vaak met proteïnurie; bijv. IgA-nefropathie) of niet-glomerulair (stenen, infecties, tumoren van nier, ureter of blaas). Bij ouderen en rokers moet bij hematurie een urologische maligniteit worden uitgesloten.</p>","image_url":"","wiki_title":"Hematuria","match":"microscopische hematurie|hematurie","option_only":true},"blaascarcinoom":{"title":"Blaascarcinoom","short":"Het blaascarcinoom is meestal een urotheelcelcarcinoom; roken is de belangrijkste risicofactor.","definition":"<p>Het <strong>blaascarcinoom</strong> presenteert zich vaak met pijnloze macroscopische hematurie. Risicofactoren zijn roken, beroepsmatige blootstelling aan aromatische aminen (verf, rubber) en (in Afrika) schistosomiasis (plaveiselcelcarcinoom). Niet-spierinvasieve tumoren worden transurethraal verwijderd en komen vaak terug; spierinvasieve tumoren vereisen cystectomie of radiotherapie.</p>","image_url":"","wiki_title":"Bladder cancer","match":"blaascarcinoom|blaaskanker|urotheelcelcarcinoom","option_only":true},"niercarcinoom":{"title":"Niercelcarcinoom","short":"Het niercelcarcinoom is een kwaadaardige tumor van het nierepitheel, meestal van het heldercellige type.","definition":"<p>Het <strong>niercelcarcinoom</strong> wordt vaak toevallig ontdekt op beeldvorming. De klassieke trias (hematurie, flankpijn, palpabele massa) is zeldzaam. Paraneoplastische verschijnselen zijn polycytemie (EPO), hypercalciëmie en koorts. Risicofactoren: roken, obesitas, hypertensie en het von Hippel-Lindau-syndroom. Het groeit soms in de nierader en v. cava in.</p>","image_url":"","wiki_title":"Renal cell carcinoma","match":"niercarcinoom|niercelcarcinoom|nierkanker","option_only":true},"uretercarcinoom":{"title":"Urotheelcelcarcinoom van de hoge urinewegen","short":"Een uretercarcinoom is een urotheelcelcarcinoom van de ureter of het nierbekken.","definition":"<p>Tumoren van de <strong>hoge urinewegen</strong> zijn veel zeldzamer dan blaastumoren, maar hebben dezelfde risicofactoren (roken, aromatische aminen) en zijn ook geassocieerd met het Lynch-syndroom. Ze geven hematurie en soms flankpijn door obstructie. Na een tumor in de hoge urinewegen ontstaan vaak later ook blaastumoren.</p>","image_url":"","wiki_title":"Transitional cell carcinoma","match":"uretercarcinoom|carcinoom van de ureter","option_only":true},"testiscarcinoom":{"title":"Testiscarcinoom","short":"Testiscarcinoom is een kwaadaardige kiemceltumor van de zaadbal, vooral bij jonge mannen.","definition":"<p><strong>Testistumoren</strong> zijn meestal kiemceltumoren: seminomen en non-seminomen. Ze presenteren zich als een pijnloze, harde zwelling van de testis. Een niet-ingedaalde testis is een belangrijke risicofactor. Tumormarkers zijn AFP, β-hCG en LDH. De behandeling start met een orchidectomie via de lies; de genezingskans is zeer hoog, ook bij uitzaaiingen.</p>","image_url":"","wiki_title":"Testicular cancer","match":"testiscarcinoom|zaadbalkanker|testistumor","option_only":true},"pancreascarcinoom":{"title":"Pancreascarcinoom","short":"Het pancreascarcinoom is een agressieve tumor, meestal een ductaal adenocarcinoom, met een slechte prognose.","definition":"<p>Het <strong>pancreascarcinoom</strong> zit vaak in de pancreaskop, waar het de galweg afsluit: pijnloze icterus, een palpabele galblaas (teken van Courvoisier), jeuk, ontkleurde ontlasting en donkere urine. Tumoren in corpus en staart worden later ontdekt (rugpijn, gewichtsverlies). Risicofactoren zijn roken, chronische pancreatitis en erfelijke aanleg. Slechts een minderheid is operabel (Whipple).</p>","image_url":"","wiki_title":"Pancreatic cancer","match":"pancreascarcinoom|alvleesklierkanker|pancreaskopcarcinoom","option_only":true},"cervixcarcinoom":{"title":"Cervixcarcinoom","short":"Het cervixcarcinoom is kanker van de baarmoederhals, vrijwel altijd veroorzaakt door een persisterende infectie met hoog-risico-HPV.","definition":"<p>Het <strong>cervixcarcinoom</strong> ontstaat via voorstadia (CIN) in de transformatiezone, meestal als plaveiselcelcarcinoom. Klachten: contactbloedingen (na gemeenschap), intermenstrueel bloedverlies en afscheiding. Preventie via HPV-vaccinatie en het bevolkingsonderzoek (hrHPV-test). Behandeling afhankelijk van stadium: operatie of (chemo)radiatie.</p>","image_url":"","wiki_title":"Cervical cancer","match":"cervixcarcinoom|baarmoederhalskanker","option_only":true},"endometriumcarcinoom":{"title":"Endometriumcarcinoom","short":"Het endometriumcarcinoom is kanker van het baarmoederslijmvlies, typisch met bloedverlies na de menopauze.","definition":"<p>Het <strong>endometriumcarcinoom</strong> (type 1) hangt samen met langdurige blootstelling aan oestrogenen zonder progesteron: obesitas, weinig zwangerschappen, PCOS, tamoxifen en het Lynch-syndroom. Het presenteert zich meestal vroeg met postmenopauzaal bloedverlies en heeft dan een goede prognose. Diagnostiek met een transvaginale echo en een endometriumbiopt.</p>","image_url":"","wiki_title":"Endometrial cancer","match":"endometriumcarcinoom|baarmoederkanker|baarmoederslijmvlieskanker","option_only":true},"pet/ct":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"pet/ct|pet-ct|pet-scan","option_only":true},"skeletfoto's":{"title":"Skeletstatus (skeletfoto's)","short":"Bij een skeletstatus worden röntgenfoto's van het hele skelet gemaakt, bijv. bij verdenking op multipel myeloom of kindermishandeling.","definition":"<p>Een <strong>skeletstatus</strong> wordt o.a. gebruikt om lytische botlaesies op te sporen bij multipel myeloom (tegenwoordig vaak vervangen door low-dose CT of MRI), en bij jonge kinderen bij verdenking op mishandeling, om oude en nieuwe fracturen in beeld te brengen. Ook bij skeletdysplasieën wordt het gebruikt.</p>","image_url":"","wiki_title":"Skeletal survey","match":"skeletfoto's|skeletstatus|skeletonderzoek","option_only":true},"foliumzuur deficientie":{"title":"Foliumzuurdeficiëntie","short":"Een tekort aan foliumzuur geeft een macrocytaire (megaloblastaire) anemie en verhoogt in de zwangerschap het risico op een neuralebuisdefect.","definition":"<p>Een <strong>foliumzuurtekort</strong> ontstaat door weinig groenten in de voeding, alcoholisme, malabsorptie (coeliakie), verhoogde behoefte (zwangerschap, hemolyse) of medicatie (methotrexaat, trimethoprim, anti-epileptica). Anders dan bij B12-tekort zijn er geen neurologische afwijkingen en is het methylmalonzuur normaal; homocysteïne is bij beide verhoogd.</p>","image_url":"","wiki_title":"Folate deficiency","match":"foliumzuur deficientie|foliumzuurdeficiëntie|foliumzuurtekort","option_only":true},"vitamine b12 deficientie":{"title":"Vitamine B12-deficiëntie","short":"Een vitamine B12-tekort geeft een macrocytaire anemie en neurologische schade, zoals polyneuropathie en een gecombineerde strengziekte.","definition":"<p>Oorzaken van een <strong>B12-tekort</strong> zijn auto-immuungastritis (pernicieuze anemie, antistoffen tegen intrinsieke factor), maag- of ileumresectie, ziekte van Crohn, metformine, langdurig PPI-gebruik en veganistisch eten. Naast anemie ontstaan neuropathie, degeneratie van achterstrengen en piramidebanen, cognitieve stoornissen en glossitis. Methylmalonzuur en homocysteïne zijn verhoogd.</p>","image_url":"","wiki_title":"Vitamin B12 deficiency","match":"vitamine b12 deficientie|vitamine b12-deficiëntie|b12-tekort|pernicieuze anemie","option_only":true},"leucocytose":{"title":"Leukocytose","short":"Leukocytose is een verhoogd aantal witte bloedcellen, meestal door infectie of ontsteking.","definition":"<p>Bij <strong>leukocytose</strong> is het aantal leukocyten boven ongeveer 10 × 10⁹/L. Een neutrofiele leukocytose met linksverschuiving past bij bacteriële infectie; ook stress, corticosteroïden, roken, trauma en necrose kunnen het verhogen. Sterk verhoogde waarden met onrijpe cellen in het bloed wijzen op leukemie of een leukemoïde reactie.</p>","image_url":"","wiki_title":"Leukocytosis","match":"leucocytose","option_only":true},"niet-steroïdale anti-inflammatoire drugs (nsaids)":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"niet-steroïdale anti-inflammatoire drugs (nsaids)","option_only":true},"nsaid’s":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"nsaid’s","option_only":true},"hoge koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"hoge koorts","option_only":true},"alfa thalassemie":{"title":"Alfa-thalassemie","short":"Bij alfa-thalassemie worden te weinig alfa-globineketens gemaakt, door deletie van een of meer van de vier alfa-genen.","definition":"<p>Het beeld van <strong>alfa-thalassemie</strong> hangt af van het aantal ontbrekende genen: van stil dragerschap (1) en een lichte microcytaire anemie (2) tot HbH-ziekte (3) en hydrops foetalis (4, Hb Bart's). Dragers hebben een microcytaire anemie met een normaal ferritine, wat onderscheid met ijzergebrek belangrijk maakt.</p>","image_url":"","wiki_title":"Alpha-thalassemia","match":"alfa thalassemie|alfa-thalassemie|thalassemie","option_only":true},"polycytemia vera":{"title":"Polycytemia vera","short":"Polycytemia vera is een myeloproliferatieve neoplasie met een overmatige aanmaak van rode bloedcellen, meestal door een JAK2-mutatie.","definition":"<p>Bij <strong>polycytemia vera</strong> zijn het hemoglobine en hematocriet verhoogd, vaak ook leukocyten en plaatjes. Klachten: hoofdpijn, roodheid, jeuk na een warm bad, splenomegalie en een verhoogd risico op trombose. Secundaire polycytemie (bijv. door hypoxie bij COPD of EPO-producerende tumoren) heeft een verhoogd EPO. Behandeling met aderlatingen en acetylsalicylzuur.</p>","image_url":"","wiki_title":"Polycythemia vera","match":"polycytemia vera|polycytemie|polycythemie","option_only":true},"sikkelcelcrise":{"title":"Sikkelcelcrise","short":"Een sikkelcelcrise is een acute, pijnlijke vaso-occlusieve episode bij sikkelcelziekte.","definition":"<p>Bij een <strong>vaso-occlusieve crise</strong> blokkeren gesikkelde erytrocyten kleine vaten, met hevige pijn in botten, borst of buik. Uitlokkers zijn infecties, kou, uitdroging en hypoxie. Behandeling met pijnstilling, vocht en zuurstof. Een acute chest syndrome en een miltsekwestratie zijn gevaarlijke vormen.</p>","image_url":"","wiki_title":"Sickle cell crisis","match":"sikkelcelcrise|sikkelcelcrisis|pijncrise","option_only":true},"brentuximab":{"title":"Brentuximab vedotin","short":"Brentuximab vedotin is een antilichaam tegen CD30 gekoppeld aan een celgif; gebruikt bij het Hodgkinlymfoom en anaplastisch grootcellig lymfoom.","definition":"<p><strong>Brentuximab vedotin</strong> bindt aan CD30 op tumorcellen, wordt opgenomen en geeft dan een middel af dat de microtubuli verstoort. Een belangrijke bijwerking is perifere neuropathie.</p>","image_url":"","wiki_title":"Brentuximab vedotin","match":"brentuximab|brentuximab vedotin","option_only":true},"abciximab":{"title":"Abciximab","short":"Abciximab is een antilichaamfragment dat de GPIIb/IIIa-receptor op bloedplaatjes blokkeert en zo de plaatjesaggregatie sterk remt.","definition":"<p><strong>GPIIb/IIIa-remmers</strong> (abciximab, eptifibatide, tirofiban) blokkeren de laatste gemeenschappelijke stap van de plaatjesaggregatie: binding van fibrinogeen. Ze werden gebruikt bij hoog-risico PCI; het bloedingsrisico is groot.</p>","image_url":"","wiki_title":"Abciximab","match":"abciximab|gpiib/iiia-remmer","option_only":true},"testosteron":{"title":"Testosteron","short":"Testosteron is het belangrijkste mannelijke geslachtshormoon, vooral gemaakt door de cellen van Leydig in de testis.","definition":"<p>De afgifte van <strong>testosteron</strong> wordt gestuurd door LH. Het zorgt voor de mannelijke ontwikkeling (embryonaal de gangen van Wolff), puberteit, spermatogenese (samen met FSH), spiermassa, libido en botdichtheid. In weefsels wordt het door 5α-reductase omgezet in het sterkere DHT (prostaat, huid, uitwendig genitaal) of door aromatase in oestradiol.</p>","image_url":"","wiki_title":"Testosterone","match":"testosteron","option_only":true},"cyclofosfamide":{"title":"Cyclofosfamide","short":"Cyclofosfamide is een alkylerend cytostaticum en immunosuppressivum, gebruikt bij kanker en ernstige vasculitis of lupusnefritis.","definition":"<p><strong>Cyclofosfamide</strong> wordt in de lever geactiveerd en vormt verbindingen in het DNA. Bijwerkingen: beenmergsuppressie, hemorragische cystitis (door acroleïne; preventie met mesna en ruim drinken), onvruchtbaarheid en een verhoogd risico op blaaskanker en leukemie.</p>","image_url":"","wiki_title":"Cyclophosphamide","match":"cyclofosfamide","option_only":true},"diclofenac (nsaid)":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"diclofenac (nsaid)","option_only":true},"diclofenac":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"diclofenac","option_only":true},"ibuprofen":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"ibuprofen","option_only":true},"flushing":{"title":"Flushing","short":"Flushing is plotseling, voorbijgaand rood worden van gezicht, hals en borst door vaatverwijding.","definition":"<p>Oorzaken van <strong>flushing</strong> zijn o.a. emoties, warmte, alcohol, de overgang (opvliegers), rosacea, medicatie (niacine, calciumantagonisten, nitraten) en zeldzamer het carcinoïdsyndroom, mastocytose of een feochromocytoom.</p>","image_url":"","wiki_title":"Flushing (physiology)","match":"flushing|opvliegers","option_only":true},"laparoscopische cholecystectomie":{"title":"Laparoscopische cholecystectomie","short":"Bij een laparoscopische cholecystectomie wordt de galblaas via een kijkoperatie verwijderd, de standaardbehandeling bij symptomatisch galsteenlijden.","definition":"<p>Een <strong>cholecystectomie</strong> wordt gedaan bij galsteenkolieken, cholecystitis en na een biliaire pancreatitis. Een belangrijke, gevreesde complicatie is letsel van de galweg; de chirurg identificeert daarom eerst de ‘critical view of safety’.</p>","image_url":"","wiki_title":"Cholecystectomy","match":"laparoscopische cholecystectomie|cholecystectomie","option_only":true},"kortademigheid":{"title":"Dyspneu (kortademigheid)","short":"Dyspneu is het subjectieve gevoel van moeilijk of onvoldoende kunnen ademen.","definition":"<p><strong>Kortademigheid</strong> kan een pulmonale oorzaak hebben (astma, COPD, pneumonie, longembolie, pneumothorax), een cardiale (hartfalen, ischemie, ritmestoornissen), of samenhangen met anemie, obesitas, conditieverlies, angst of metabole acidose. Het tijdsbeloop (acuut of chronisch) en bijkomende klachten sturen de diagnostiek.</p>","image_url":"","wiki_title":"Shortness of breath","match":"kortademigheid|dyspneu|dyspnoe|benauwdheid","option_only":true},"methadon":{"title":"Methadon","short":"Methadon is een langwerkend opioïd dat wordt gebruikt bij opioïdverslaving en bij pijn.","definition":"<p><strong>Methadon</strong> heeft een lange en per persoon wisselende halfwaardetijd, waardoor het onttrekkingsverschijnselen en craving voorkomt. Het wordt ook bij moeilijk behandelbare pijn gebruikt (NMDA-antagonisme). Risico's zijn accumulatie, ademhalingsdepressie en QT-verlenging.</p>","image_url":"","wiki_title":"Methadone","match":"methadon|methadone","option_only":true},"fentanyl":{"title":"Fentanyl","short":"Fentanyl is een zeer krachtig synthetisch opioïd, o.a. als pleister of intraveneus gebruikt.","definition":"<p><strong>Fentanyl</strong> is ongeveer 100 keer zo krachtig als morfine. Als pleister geeft het een gelijkmatige afgifte over drie dagen bij chronische pijn. Het wordt via de lever (CYP3A4) afgebroken en is daardoor bruikbaar bij nierfalen. Illegaal gebruik veroorzaakt veel overdoseringen.</p>","image_url":"","wiki_title":"Fentanyl","match":"fentanyl","option_only":true},"buprenorfine":{"title":"Buprenorfine","short":"Buprenorfine is een partiële µ-opioïdagonist, gebruikt bij pijn (pleister) en als onderhoudsbehandeling bij opioïdverslaving.","definition":"<p>Omdat <strong>buprenorfine</strong> een partiële agonist met hoge affiniteit is, geeft het minder ademhalingsdepressie (plafondeffect) en kan het bij iemand die nog volle agonisten gebruikt onttrekking uitlokken. Het wordt vaak gecombineerd met naloxon om intraveneus misbruik tegen te gaan.</p>","image_url":"","wiki_title":"Buprenorphine","match":"buprenorfine","option_only":true},"hydromorfon":{"title":"Hydromorfon","short":"Hydromorfon is een sterk opioïd, vergelijkbaar met morfine maar ongeveer vijf keer zo krachtig.","definition":"<p><strong>Hydromorfon</strong> wordt gebruikt bij ernstige pijn, vooral in de palliatieve zorg en als alternatief bij bijwerkingen van morfine (opioïdrotatie). Het heeft minder actieve metabolieten die zich bij nierfalen ophopen.</p>","image_url":"","wiki_title":"Hydromorphone","match":"hydromorfon|hydromorphone","option_only":true},"maligne melanoom":{"title":"Melanoom","short":"Het melanoom is een kwaadaardige tumor van melanocyten; vroeg ontdekt goed te behandelen, gemetastaseerd gevaarlijk.","definition":"<p>Risicofactoren voor een <strong>melanoom</strong> zijn zonverbranding (vooral in de jeugd), een lichte huid, veel of atypische moedervlekken en familiaire belasting. Waarschuwingssignalen (ABCDE): asymmetrie, onregelmatige grens, kleurverschillen, diameter &gt;6 mm en evolutie. De Breslow-dikte bepaalt de prognose; immunotherapie en doelgerichte therapie (BRAF) hebben de behandeling veranderd.</p>","image_url":"","wiki_title":"Melanoma","match":"maligne melanoom|melanoom","option_only":true},"lever metastasen":{"title":"Levermetastasen","short":"Levermetastasen zijn uitzaaiingen in de lever, vaak van tumoren uit het maag-darmkanaal via de v. portae.","definition":"<p>De lever is een veelvoorkomende plaats voor <strong>metastasen</strong>, vooral van colorectaal, pancreas-, maag-, borst- en longcarcinoom en melanoom. Bij beperkte levermetastasen van een colorectaal carcinoom kan resectie of ablatie nog curatief zijn.</p>","image_url":"","wiki_title":"Liver metastasis","match":"lever metastasen|levermetastasen|hepatogene metastasen","option_only":true},"cerebrale metastasen":{"title":"Hersenmetastasen","short":"Hersenmetastasen zijn uitzaaiingen in het brein, vooral van long- en borstkanker en melanoom.","definition":"<p><strong>Hersenmetastasen</strong> geven hoofdpijn, epileptische aanvallen, focale uitval, gedragsverandering of tekenen van verhoogde druk. Ze liggen vaak op de grens van grijze en witte stof en zijn omgeven door oedeem (dexamethason). Behandeling met stereotactische radiotherapie, chirurgie of systemische therapie.</p>","image_url":"","wiki_title":"Brain metastasis","match":"cerebrale metastasen|hersenmetastasen","option_only":true},"sarcoom":{"title":"Sarcoom","short":"Een sarcoom is een kwaadaardige tumor van bindweefsel, zoals bot, kraakbeen, vet of spier.","definition":"<p><strong>Sarcomen</strong> zijn zeldzaam en worden ingedeeld in botsarcomen (bijv. osteosarcoom, Ewing-sarcoom) en wekedelensarcomen (bijv. liposarcoom, leiomyosarcoom). Ze zaaien vaak via het bloed uit, vooral naar de longen. Een snel groeiende, diepe zwelling groter dan 5 cm moet worden verwezen naar een sarcoomcentrum.</p>","image_url":"","wiki_title":"Sarcoma","match":"sarcoom|sarcomen","option_only":true},"lymfoom":{"title":"Lymfoom","short":"Een lymfoom is een kwaadaardige ziekte van lymfocyten, meestal uitgaand van lymfeklieren.","definition":"<p><strong>Lymfomen</strong> worden ingedeeld in Hodgkinlymfomen en non-Hodgkinlymfomen (B-, T- of NK-cel). Klachten zijn pijnloze lymfeklierzwelling, B-symptomen (koorts, nachtzweten, gewichtsverlies), jeuk en klachten door orgaaninfiltratie. Diagnose met een klierbiopt.</p>","image_url":"","wiki_title":"Lymphoma","match":"lymfoom|lymfomen","option_only":true},"immunotherapie":{"title":"Immunotherapie","short":"Immunotherapie gebruikt of versterkt het afweersysteem om ziekten, vooral kanker, te behandelen.","definition":"<p>Bij kanker worden o.a. <strong>checkpointremmers</strong> (antistoffen tegen PD-1, PD-L1 of CTLA-4) gebruikt, die de rem op T-cellen opheffen. Bijwerkingen zijn immuungerelateerde ontstekingen van o.a. darm, huid, lever, schildklier en longen. Ook allergeen-immunotherapie (desensibilisatie) valt onder de term.</p>","image_url":"","wiki_title":"Immunotherapy","match":"immunotherapie|checkpointremmers","option_only":true},"splenectomie":{"title":"Splenectomie","short":"Een splenectomie is het operatief verwijderen van de milt.","definition":"<p>Na <strong>splenectomie</strong> is er een levenslang verhoogd risico op een fulminante sepsis met gekapselde bacteriën (pneumokok, meningokok, <em>H. influenzae</em>). Daarom worden patiënten vooraf gevaccineerd en krijgen ze uitleg over het direct starten van antibiotica bij koorts. Het bloeduitstrijkje toont Howell-Jolly-lichaampjes.</p>","image_url":"","wiki_title":"Splenectomy","match":"splenectomie|miltverwijdering","option_only":true},"hepatosplenomegalie":{"title":"Hepatosplenomegalie","short":"Hepatosplenomegalie is een gelijktijdige vergroting van lever en milt.","definition":"<p>Oorzaken van <strong>hepatosplenomegalie</strong> zijn o.a. infecties (EBV, CMV, malaria, leishmaniasis), hematologische ziekten (leukemie, lymfoom, myeloproliferatieve ziekten, hemolyse), portale hypertensie, stapelingsziekten (Gaucher) en congestief hartfalen.</p>","image_url":"","wiki_title":"Hepatosplenomegaly","match":"hepatosplenomegalie","option_only":true},"dwarslaesie":{"title":"Dwarslaesie","short":"Bij een dwarslaesie is het ruggenmerg (deels) onderbroken, met uitval van kracht, gevoel en autonome functies onder het niveau van de laesie.","definition":"<p>Een <strong>dwarslaesie</strong> ontstaat door trauma, compressie (tumor, abces, hernia), ischemie of ontsteking. Acuut kan een spinale shock optreden (slappe verlamming, areflexie), later spasticiteit. Bij hoge laesies kan autonome dysreflexie ontstaan. Een acute compressie is een neurochirurgisch spoedgeval.</p>","image_url":"","wiki_title":"Spinal cord injury","match":"dwarslaesie|ruggenmergletsel","option_only":true},"plasmodium falciparum malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium falciparum malaria","option_only":true},"oxycodon (oxycontin/oxynorm)":{"title":"Oxycodon","short":"Oxycodon is een sterk werkend opioïd voor (matig) ernstige pijn.","definition":"<p><strong>Oxycodon</strong> is een µ-opioïdreceptoragonist met een vergelijkbaar effect en bijwerkingenprofiel als morfine (obstipatie, sufheid, ademhalingsdepressie). Het wordt via de lever (CYP3A4, CYP2D6) omgezet en is daarom een alternatief bij nierfunctiestoornissen. Er zijn snel- en langwerkende vormen; misbruik is een probleem.</p>","image_url":"","wiki_title":"Oxycodone","match":"oxycodon (oxycontin/oxynorm)","option_only":true},"diclofenac (een nsaid)":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"diclofenac (een nsaid)","option_only":true},"non hodgkin lymfoom":{"title":"Non-Hodgkinlymfoom","short":"Non-Hodgkinlymfomen zijn een grote groep kwaadaardige ziekten van B-, T- of NK-cellen, van indolent tot zeer agressief.","definition":"<p><strong>Non-Hodgkinlymfomen</strong> worden ingedeeld naar celtype en gedrag. Indolente vormen (bijv. folliculair lymfoom) groeien langzaam maar zijn vaak niet te genezen; agressieve vormen (bijv. diffuus grootcellig B-cellymfoom, Burkitt) groeien snel maar zijn vaak wel curabel. Klachten: pijnloze lymfeklierzwelling, B-symptomen en extranodale lokalisaties.</p>","image_url":"","wiki_title":"Non-Hodgkin lymphoma","match":"non hodgkin lymfoom","option_only":true},"hpv-virus":{"title":"Humaan papillomavirus (HPV)","short":"HPV is een DNA-virus dat wratten veroorzaakt; hoog-risicotypes (o.a. 16 en 18) veroorzaken baarmoederhalskanker en andere kankers.","definition":"<p>Het <strong>humaan papillomavirus</strong> infecteert basale cellen van huid en slijmvlies. Laag-risicotypes (6, 11) geven wratten en condylomata acuminata. Hoog-risicotypes maken de eiwitten E6 en E7, die p53 en Rb uitschakelen; persisterende infectie kan leiden tot cervixcarcinoom en kankers van anus, vulva, penis en orofarynx. Er is een vaccin en een bevolkingsonderzoek met hrHPV-test.</p>","image_url":"","wiki_title":"Human papillomavirus infection","match":"hpv-virus","option_only":true},"ebv-virus":{"title":"Epstein-Barrvirus (EBV)","short":"EBV is een herpesvirus dat B-cellen infecteert; het veroorzaakt de ziekte van Pfeiffer en is geassocieerd met enkele kankers.","definition":"<p>Het <strong>Epstein-Barrvirus</strong> wordt via speeksel overgedragen. Op jonge leeftijd verloopt infectie vaak ongemerkt; bij adolescenten geeft het vaak mononucleosis infectiosa. Het virus blijft levenslang latent in B-cellen. EBV is geassocieerd met o.a. het Burkittlymfoom, het nasofarynxcarcinoom, sommige Hodgkinlymfomen en posttransplantatie-lymfoproliferatieve ziekte.</p>","image_url":"","wiki_title":"Epstein–Barr virus","match":"ebv-virus","option_only":true},"acute leukemie":{"title":"Acute myeloïde leukemie (AML)","short":"AML is een agressieve kanker van het beenmerg waarbij onrijpe myeloïde voorlopercellen (blasten) zich ophopen.","definition":"<p>Bij <strong>AML</strong> verdringen myeloblasten (≥20% in het beenmerg) de normale bloedaanmaak, met anemie, trombocytopenie (bloedingen) en neutropenie (infecties). Het komt vooral bij ouderen voor. Blasten kunnen Auerstaafjes bevatten. Bij acute promyelocytenleukemie (t(15;17)) dreigt diffuse intravasale stolling; die vorm reageert goed op all-trans-retinoïnezuur. Behandeling met intensieve chemotherapie, eventueel stamceltransplantatie.</p>","image_url":"","wiki_title":"Acute myeloid leukemia","match":"acute leukemie","option_only":true},"pet scan":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"pet scan","option_only":true},"pet-ct scan":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"pet-ct scan","option_only":true},"pet/ct body":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"pet/ct body","option_only":true},"pet/ct abdomen":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"pet/ct abdomen","option_only":true},"hepatocellulair carcinoom":{"title":"Hepatocellulair carcinoom (HCC)","short":"Het hepatocellulair carcinoom is primaire leverkanker uitgaand van hepatocyten, meestal in een cirrotische lever.","definition":"<p><strong>HCC</strong> ontstaat vooral bij cirrose door alcohol, NASH of chronische hepatitis B en C (bij hepatitis B ook zonder cirrose). Patiënten met cirrose worden halfjaarlijks gescreend met echo, eventueel met AFP. Behandeling hangt af van tumorgrootte en leverfunctie: resectie, ablatie, transplantatie of systemische therapie.</p>","image_url":"","wiki_title":"Hepatocellular carcinoma","match":"hepatocellulair carcinoom|hcc|levercelcarcinoom","option_only":true},"chronische atrofische gastritis":{"title":"Chronische atrofische gastritis","short":"Bij atrofische gastritis verdwijnen de maagklieren door chronische ontsteking, auto-immuun of door H. pylori.","definition":"<p>Bij de <strong>auto-immuunvorm</strong> (corpus) ontstaan antistoffen tegen pariëtale cellen en intrinsieke factor, met achloorhydrie, vitamine B12-tekort (pernicieuze anemie) en hypergastrinemie. Bij de H. pylori-vorm (antrum, later uitbreidend) is er een verhoogd risico op intestinale metaplasie en maagcarcinoom.</p>","image_url":"","wiki_title":"Atrophic gastritis","match":"chronische atrofische gastritis|atrofische gastritis|auto-immuun gastritis","option_only":true},"imatinib":{"title":"Imatinib","short":"Imatinib is een tyrosinekinaseremmer die het BCR-ABL-eiwit remt; het heeft de behandeling van CML sterk veranderd.","definition":"<p><strong>Imatinib</strong> blokkeert de ATP-bindingsplaats van BCR-ABL en ook van KIT, en wordt gebruikt bij chronische myeloïde leukemie en gastro-intestinale stromatumoren (GIST). Bijwerkingen: oedeem, spierkrampen, misselijkheid en cytopenieën.</p>","image_url":"","wiki_title":"Imatinib","match":"imatinib|tyrosinekinaseremmer","option_only":true},"ruxolitinib":{"title":"Ruxolitinib","short":"Ruxolitinib is een JAK1/2-remmer, gebruikt bij myelofibrose en polycytemia vera.","definition":"<p><strong>Ruxolitinib</strong> remt de overactieve JAK-STAT-signalering bij myeloproliferatieve ziekten. Het verkleint de milt en vermindert algemene klachten. Bijwerkingen: anemie, trombocytopenie en een verhoogd infectierisico.</p>","image_url":"","wiki_title":"Ruxolitinib","match":"ruxolitinib|jak-remmer","option_only":true},"essentiële trombocytose":{"title":"Essentiële trombocytemie","short":"Essentiële trombocytemie is een myeloproliferatieve ziekte met een blijvend sterk verhoogd aantal bloedplaatjes.","definition":"<p>Bij <strong>essentiële trombocytemie</strong> (vaak JAK2-, CALR- of MPL-mutatie) is er een verhoogd risico op trombose en, bij zeer hoge waarden, juist op bloedingen (verworven von Willebrand). Reactieve oorzaken (ijzergebrek, ontsteking, na splenectomie) moeten eerst worden uitgesloten. Behandeling met acetylsalicylzuur en soms hydroxycarbamide.</p>","image_url":"","wiki_title":"Essential thrombocythemia","match":"essentiële trombocytose|essentiële trombocytemie","option_only":true},"myelofibrose":{"title":"Myelofibrose","short":"Bij myelofibrose verbindweefselt het beenmerg, waardoor de bloedaanmaak naar milt en lever verschuift.","definition":"<p>Bij <strong>primaire myelofibrose</strong> ontstaan anemie, een sterk vergrote milt (extramedullaire hematopoëse), algemene klachten en een leuko-erytroblastair bloedbeeld met traanvormige erytrocyten. Een beenmergaspiraat lukt vaak niet (‘dry tap’). Behandeling o.a. met JAK-remmers; stamceltransplantatie is de enige curatieve optie.</p>","image_url":"","wiki_title":"Primary myelofibrosis","match":"myelofibrose|primaire myelofibrose","option_only":true},"homozygote beta-thalassemie":{"title":"Bèta-thalassemie major","short":"Bij bèta-thalassemie major worden (vrijwel) geen bèta-globineketens gemaakt, met een ernstige anemie vanaf de eerste levensmaanden.","definition":"<p>Bij <strong>bèta-thalassemie major</strong> klonteren overtollige alfaketens in de rode voorlopercellen, met ineffectieve erytropoëse, hemolyse, beenmergexpansie (botvervormingen) en hepatosplenomegalie. Patiënten zijn transfusieafhankelijk, met ijzerstapeling als gevolg (chelatie nodig). Dragers hebben een lichte microcytaire anemie met een verhoogd HbA2.</p>","image_url":"","wiki_title":"Beta thalassemia","match":"homozygote beta-thalassemie|beta-thalassemie|bèta-thalassemie|thalassemia major","option_only":true},"g6pd deficiëntie":{"title":"G6PD-deficiëntie","short":"Bij G6PD-deficiëntie zijn rode bloedcellen gevoelig voor oxidatieve stress, met hemolyse na bijv. infecties, bepaalde geneesmiddelen of tuinbonen.","definition":"<p><strong>G6PD</strong> levert via de pentosefosfaatroute NADPH, dat glutathion in rode bloedcellen actief houdt. Bij een tekort (X-gebonden) kunnen o.a. primaquine, dapson, sulfonamiden, nitrofurantoïne en tuinbonen een acute hemolyse uitlokken, met Heinz-lichaampjes en ‘bite cells’ in het uitstrijkje.</p>","image_url":"","wiki_title":"Glucose-6-phosphate dehydrogenase deficiency","match":"g6pd deficiëntie|g6pd-deficiëntie|favisme","option_only":true},"acute chest syndrome":{"title":"Acute chest syndrome","short":"Het acute chest syndrome is een levensbedreigende complicatie van sikkelcelziekte met pijn op de borst, koorts, hypoxie en een nieuw infiltraat.","definition":"<p>Het <strong>acute chest syndrome</strong> ontstaat door infectie, vetembolieën uit beenmerginfarcten en sikkeling in de longvaten. Behandeling: zuurstof, antibiotica, pijnstilling, incentive spirometrie en (wissel)transfusie.</p>","image_url":"","wiki_title":"Acute chest syndrome","match":"acute chest syndrome","option_only":true},"neutropene koorts":{"title":"Neutropene koorts","short":"Neutropene koorts is koorts bij een sterk verlaagd aantal neutrofielen (meestal <0,5 × 10⁹/L), bijv. na chemotherapie; een medisch spoedgeval.","definition":"<p>Bij <strong>neutropene koorts</strong> kan een infectie zonder duidelijke ontstekingsverschijnselen snel tot sepsis leiden. Na bloedkweken wordt binnen een uur gestart met breedspectrum-antibiotica die ook <em>Pseudomonas</em> dekken.</p>","image_url":"","wiki_title":"Febrile neutropenia","match":"neutropene koorts|febriele neutropenie","option_only":true},"cisplatin":{"title":"Cisplatine","short":"Cisplatine is een platinabevattend cytostaticum dat DNA-strengen aan elkaar koppelt.","definition":"<p><strong>Cisplatine</strong> wordt gebruikt bij o.a. testis-, long-, blaas-, hoofd-hals- en ovariumkanker. Belangrijke bijwerkingen zijn nefrotoxiciteit (voorkomen met ruime hydratie), ototoxiciteit, neuropathie, hypomagnesiëmie en zeer emetogene misselijkheid.</p>","image_url":"","wiki_title":"Cisplatin","match":"cisplatin|cisplatine|carboplatine|platinaverbindingen","option_only":true},"paclitaxel":{"title":"Paclitaxel (taxanen)","short":"Paclitaxel is een taxaan dat de microtubuli stabiliseert, waardoor de celdeling in de mitose stopt.","definition":"<p><strong>Taxanen</strong> worden gebruikt bij o.a. borst-, ovarium- en longkanker. Bijwerkingen zijn beenmergsuppressie, perifere neuropathie, haaruitval en overgevoeligheidsreacties (premedicatie met corticosteroïden en antihistaminica).</p>","image_url":"","wiki_title":"Paclitaxel","match":"paclitaxel|docetaxel|taxanen","option_only":true},"doxorubicine":{"title":"Doxorubicine","short":"Doxorubicine is een antracycline-cytostaticum; de belangrijkste lange-termijnbijwerking is cardiotoxiciteit.","definition":"<p><strong>Antracyclines</strong> remmen topo-isomerase II en vormen vrije radicalen. Ze worden gebruikt bij o.a. borstkanker, lymfomen en sarcomen. Door cumulatieve, dosisafhankelijke schade aan het hart kan cardiomyopathie ontstaan, ook jaren later; daarom wordt de hartfunctie gecontroleerd. Andere bijwerkingen: beenmergsuppressie, haaruitval en rode urine.</p>","image_url":"","wiki_title":"Doxorubicin","match":"doxorubicine|antracyclines|antracycline","option_only":true},"hemoglobine":{"title":"Hemoglobine","short":"Hemoglobine is het eiwit in rode bloedcellen dat zuurstof bindt en vervoert.","definition":"<p>Volwassen <strong>hemoglobine</strong> (HbA) bestaat uit twee alfa- en twee bètaketens, elk met een heemgroep met ijzer. De zuurstofbinding is coöperatief (S-vormige dissociatiecurve); een lagere pH, hogere CO₂, temperatuur en 2,3-BPG verschuiven de curve naar rechts (makkelijker afgifte). Foetaal Hb (HbF) heeft een hogere affiniteit voor zuurstof.</p>","image_url":"","wiki_title":"Hemoglobin","match":"hemoglobine|hb","option_only":true},"antidepressiva":{"title":"Antidepressiva","short":"Antidepressiva zijn geneesmiddelen tegen depressie en angststoornissen, die vooral de serotonerge en noradrenerge overdracht beïnvloeden.","definition":"<p>Groepen zijn SSRI's (bijv. sertraline, citalopram), SNRI's (venlafaxine, duloxetine), tricyclische antidepressiva, mirtazapine en MAO-remmers. Het effect treedt na 2–6 weken op. Bij jongeren kan in het begin de suïcidaliteit toenemen; abrupt stoppen geeft onttrekkingsverschijnselen.</p>","image_url":"","wiki_title":"Antidepressant","match":"antidepressiva|antidepressivum","option_only":true},"intravesicale spoelingen":{"title":"Intravesicale spoelingen (BCG)","short":"Bij intravesicale spoelingen wordt een middel (BCG of chemotherapie) in de blaas gebracht om terugkeer van niet-spierinvasieve blaastumoren te voorkomen.","definition":"<p><strong>BCG-spoelingen</strong> wekken een lokale afweerreactie op tegen tumorcellen. Bijwerkingen zijn blaasirritatie, koorts en zeldzaam een systemische BCG-infectie. Spoelingen met mitomycine C zijn een alternatief.</p>","image_url":"","wiki_title":"Bacillus Calmette–Guérin","match":"intravesicale spoelingen|bcg-spoelingen|blaasspoelingen","option_only":true},"radicale cystectomie":{"title":"Radicale cystectomie","short":"Bij een radicale cystectomie wordt de blaas (met bij de man de prostaat) verwijderd, meestal bij een spierinvasief blaascarcinoom.","definition":"<p>Na een <strong>cystectomie</strong> wordt de urine afgeleid via een urostoma (Bricker) of een nieuwe blaas van darmweefsel (neoblaas). Vaak wordt vooraf neoadjuvante chemotherapie gegeven.</p>","image_url":"","wiki_title":"Cystectomy","match":"radicale cystectomie|cystectomie","option_only":true},"maagresectie":{"title":"Maagresectie","short":"Bij een maagresectie wordt (een deel van) de maag verwijderd, bijv. bij maagkanker.","definition":"<p>Na een <strong>(partiële) gastrectomie</strong> kunnen dumpingklachten, vitamine B12-tekort (minder intrinsieke factor), ijzergebrek en botontkalking ontstaan. Bij een totale gastrectomie is levenslang B12-suppletie nodig.</p>","image_url":"","wiki_title":"Gastrectomy","match":"maagresectie|gastrectomie","option_only":true},"hemicolectomie links":{"title":"Hemicolectomie","short":"Bij een hemicolectomie wordt de linker- of rechterhelft van de dikke darm verwijderd, meestal wegens een tumor.","definition":"<p>Bij een <strong>rechter hemicolectomie</strong> worden het terminale ileum, caecum, colon ascendens en een deel van het transversum verwijderd; bij een <strong>linker</strong> het colon descendens en soms het sigmoïd. Met de darm wordt het bijbehorende mesenterium met lymfeklieren weggenomen voor stadiëring.</p>","image_url":"","wiki_title":"Colectomy","match":"hemicolectomie links|hemicolectomie|hemicolectomie rechts","option_only":true},"ovariumcarcinoom":{"title":"Ovariumcarcinoom","short":"Het ovariumcarcinoom is kanker van de eierstok, vaak laat ontdekt doordat klachten vaag zijn.","definition":"<p>Het meest voorkomende type is het hooggradig sereus carcinoom. Klachten: opgeblazen gevoel, toename van de buikomvang (ascites), vroege verzadiging en plasklachten. Risicofactoren: BRCA1/2-mutaties, Lynch-syndroom, weinig zwangerschappen. Het CA-125 is vaak verhoogd. Behandeling met chirurgie en chemotherapie.</p>","image_url":"","wiki_title":"Ovarian cancer","match":"ovariumcarcinoom|eierstokkanker","option_only":true},"urethracarcinoom":{"title":"Urethracarcinoom","short":"Het urethracarcinoom is een zeldzame kwaadaardige tumor van de urinebuis.","definition":"<p>Een <strong>urethracarcinoom</strong> kan een urotheel-, plaveiselcel- of adenocarcinoom zijn. Klachten: bloed uit de urinebuis, plasproblemen en een palpabele zwelling. Risicofactoren zijn chronische ontsteking, strictuur en HPV.</p>","image_url":"","wiki_title":"Urethral cancer","match":"urethracarcinoom","option_only":true},"desmoïd tumor":{"title":"Desmoïdtumor","short":"Een desmoïdtumor is een lokaal agressieve bindweefseltumor die niet uitzaait, maar wel ingroeit en vaak terugkomt.","definition":"<p><strong>Desmoïdtumoren</strong> ontstaan in de buikwand, het mesenterium of de ledematen, vaker bij jonge vrouwen en bij familiaire adenomateuze polyposis (FAP, syndroom van Gardner). Afhankelijk van de groei wordt afgewacht, medicamenteus behandeld of geopereerd.</p>","image_url":"","wiki_title":"Aggressive fibromatosis","match":"desmoïd tumor|desmoïdtumor|agressieve fibromatose","option_only":true},"auto immuun hemolytische anemie":{"title":"Auto-immuun hemolytische anemie","short":"Bij AIHA maakt het lichaam antistoffen tegen de eigen rode bloedcellen, die daardoor worden afgebroken; de directe antiglobulinetest (Coombs) is positief.","definition":"<p>Bij <strong>auto-immuun hemolytische anemie</strong> binden auto-antistoffen aan erytrocyten, die vervolgens vooral in de milt worden afgebroken (type II-overgevoeligheid). Bij <em>warme</em> AIHA gaat het om IgG; bij <em>koude</em> AIHA om IgM met complementactivatie.</p><p>Laboratorium: anemie met verhoogde reticulocyten, verhoogd LDH en ongeconjugeerd bilirubine, verlaagd haptoglobine, sferocyten en een positieve directe antiglobulinetest (Coombs). Oorzaken: idiopathisch, lymfoproliferatieve ziekten, SLE, infecties (Mycoplasma, EBV) of geneesmiddelen.</p>","image_url":"","wiki_title":"Autoimmune hemolytic anemia","match":"auto immuun hemolytische anemie","option_only":true},"polycythemia vera":{"title":"Polycytemia vera","short":"Polycytemia vera is een myeloproliferatieve neoplasie met een overmatige aanmaak van rode bloedcellen, meestal door een JAK2-mutatie.","definition":"<p>Bij <strong>polycytemia vera</strong> zijn het hemoglobine en hematocriet verhoogd, vaak ook leukocyten en plaatjes. Klachten: hoofdpijn, roodheid, jeuk na een warm bad, splenomegalie en een verhoogd risico op trombose. Secundaire polycytemie (bijv. door hypoxie bij COPD of EPO-producerende tumoren) heeft een verhoogd EPO. Behandeling met aderlatingen en acetylsalicylzuur.</p>","image_url":"","wiki_title":"Polycythemia vera","match":"polycythemia vera","option_only":true},"auto-immuun trombopenie":{"title":"Immuuntrombocytopenie (ITP)","short":"Bij ITP breken auto-antistoffen tegen bloedplaatjes deze af, met een geïsoleerde trombocytopenie.","definition":"<p>Bij <strong>immuuntrombocytopenie</strong> worden plaatjes met antistoffen beladen en in de milt afgebroken; ook de aanmaak wordt geremd. Bij kinderen volgt het vaak op een virale infectie en herstelt het meestal spontaan; bij volwassenen is het vaker chronisch. Het is een diagnose na uitsluiting van andere oorzaken. Behandeling bij bloedingen of zeer lage waarden: corticosteroïden, immunoglobulinen, TPO-agonisten.</p>","image_url":"","wiki_title":"Immune thrombocytopenic purpura","match":"auto-immuun trombopenie","option_only":true},"vitamine-b12-deficiëntie":{"title":"Vitamine B12-deficiëntie","short":"Een vitamine B12-tekort geeft een macrocytaire anemie en neurologische schade, zoals polyneuropathie en een gecombineerde strengziekte.","definition":"<p>Oorzaken van een <strong>B12-tekort</strong> zijn auto-immuungastritis (pernicieuze anemie, antistoffen tegen intrinsieke factor), maag- of ileumresectie, ziekte van Crohn, metformine, langdurig PPI-gebruik en veganistisch eten. Naast anemie ontstaan neuropathie, degeneratie van achterstrengen en piramidebanen, cognitieve stoornissen en glossitis. Methylmalonzuur en homocysteïne zijn verhoogd.</p>","image_url":"","wiki_title":"Vitamin B12 deficiency","match":"vitamine-b12-deficiëntie","option_only":true},"fdg-pet scan":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"fdg-pet scan","option_only":true},"lactaat dehydrogenase (ldh)":{"title":"Lactaatdehydrogenase (LDH)","short":"LDH is een enzym in vrijwel alle cellen dat pyruvaat en lactaat in elkaar omzet; een verhoogde bloedwaarde wijst op celschade.","definition":"<p><strong>Lactaatdehydrogenase</strong> zet pyruvaat om in lactaat (en omgekeerd) en regenereert daarbij NAD⁺, wat anaerobe glycolyse mogelijk maakt. In het bloed is LDH een aspecifieke marker van weefselschade: het is verhoogd bij hemolyse, myocardinfarct, leverschade, spierschade en snelgroeiende tumoren zoals lymfomen.</p>","image_url":"","wiki_title":"Lactate dehydrogenase","match":"lactaat dehydrogenase (ldh)","option_only":true},"primaire myelofibrose":{"title":"Myelofibrose","short":"Bij myelofibrose verbindweefselt het beenmerg, waardoor de bloedaanmaak naar milt en lever verschuift.","definition":"<p>Bij <strong>primaire myelofibrose</strong> ontstaan anemie, een sterk vergrote milt (extramedullaire hematopoëse), algemene klachten en een leuko-erytroblastair bloedbeeld met traanvormige erytrocyten. Een beenmergaspiraat lukt vaak niet (‘dry tap’). Behandeling o.a. met JAK-remmers; stamceltransplantatie is de enige curatieve optie.</p>","image_url":"","wiki_title":"Primary myelofibrosis","match":"primaire myelofibrose","option_only":true},"respiratoir syncytieelvirus":{"title":"Respiratoir syncytieel virus (RSV)","short":"RSV is een RNA-virus dat in de winter luchtweginfecties geeft, bij zuigelingen vaak bronchiolitis.","definition":"<p><strong>RSV</strong> geeft bij volwassenen meestal een verkoudheid, maar bij zuigelingen kan het de kleine luchtwegen aantasten, met piepen, benauwdheid en drinkproblemen. Ex-prematuren en kinderen met hart- of longafwijkingen lopen het meeste risico. Er bestaan antistoffen ter preventie (palivizumab, nirsevimab) en een vaccin voor zwangeren en ouderen.</p>","image_url":"","wiki_title":"Respiratory syncytial virus","match":"respiratoir syncytieelvirus|rsv|respiratoir syncytieel virus","option_only":true},"capecitabine":{"title":"Capecitabine","short":"Capecitabine is een oraal voorstadium van 5-fluorouracil, een antimetaboliet die de DNA-synthese remt.","definition":"<p><strong>Capecitabine</strong> wordt gebruikt bij colorectaal-, maag- en borstkanker. Bijwerkingen: hand-voetsyndroom, diarree en beenmergsuppressie. Bij een tekort aan het enzym DPD (DPYD-variant) kan ernstige toxiciteit optreden; daarom wordt vooraf getest.</p>","image_url":"","wiki_title":"Capecitabine","match":"capecitabine|5-fluorouracil|5-fu","option_only":true},"sikkelceltrait":{"title":"Sikkelceldragerschap","short":"Bij sikkelceldragerschap (HbAS) heeft iemand één afwijkend hemoglobinegen; meestal zonder klachten.","definition":"<p>Dragers van het <strong>sikkelcelgen</strong> zijn gedeeltelijk beschermd tegen ernstige malaria. Onder extreme omstandigheden (grote hoogte, uitdroging, zware inspanning) kunnen zeldzame complicaties optreden. Twee dragers hebben samen een kans van 25% op een kind met sikkelcelziekte.</p>","image_url":"","wiki_title":"Sickle cell trait","match":"sikkelceltrait|sikkelceldragerschap|hbas","option_only":true},"secundaire polyglobulie door roken":{"title":"Secundaire polycytemie","short":"Bij secundaire polycytemie stijgt de aanmaak van rode bloedcellen door een verhoogd EPO, bijvoorbeeld bij roken, COPD of een EPO-producerende tumor.","definition":"<p>Bij roken verhoogt koolmonoxide het percentage geblokkeerd hemoglobine, wat via weefselhypoxie de EPO-productie stimuleert. Andere oorzaken: chronische hypoxie (COPD, hoogte, slaapapneu), niertumoren en testosterongebruik. Het EPO is (normaal tot) verhoogd, anders dan bij polycytemia vera.</p>","image_url":"","wiki_title":"Secondary polycythemia","match":"secundaire polyglobulie door roken|secundaire polyglobulie|secundaire polycytemie","option_only":true},"eeg":{"title":"EEG (elektro-encefalogram)","short":"Een EEG registreert de elektrische activiteit van de hersenen via elektroden op de hoofdhuid.","definition":"<p>Een <strong>EEG</strong> wordt vooral gebruikt bij epilepsie (epileptiforme afwijkingen, type epilepsie), bij onverklaarde bewustzijnsstoornissen (non-convulsieve status, encefalopathie) en bij slaaponderzoek. Een normaal EEG tussen aanvallen sluit epilepsie niet uit.</p>","image_url":"","wiki_title":"Electroencephalography","match":"eeg|elektro-encefalogram","option_only":true},"histoplasmose":{"title":"Histoplasmose","short":"Histoplasmose is een schimmelinfectie door Histoplasma capsulatum, opgelopen via stof met vogel- of vleermuisuitwerpselen (o.a. in grotten).","definition":"<p>Meestal verloopt <strong>histoplasmose</strong> mild of met een griepachtige longontsteking. Bij afweergestoorden kan een gedissemineerde vorm ontstaan. De schimmel leeft in macrofagen.</p>","image_url":"","wiki_title":"Histoplasmosis","match":"histoplasmose|histoplasma","option_only":true},"pregabaline":{"title":"Pregabaline","short":"Pregabaline is een middel tegen neuropathische pijn, epilepsie en gegeneraliseerde angst; het remt calciumkanalen in zenuwuiteinden.","definition":"<p><strong>Pregabaline</strong> en gabapentine binden aan de α2δ-subeenheid van calciumkanalen en verminderen de afgifte van prikkelende neurotransmitters. Bijwerkingen: sufheid, duizeligheid en oedeem; er is risico op misbruik en afhankelijkheid. Bij nierfunctiestoornis is een lagere dosis nodig.</p>","image_url":"","wiki_title":"Pregabalin","match":"pregabaline|gabapentine","option_only":true},"aderlating":{"title":"Aderlating (flebotomie)","short":"Bij een aderlating wordt een hoeveelheid bloed afgenomen om het aantal rode bloedcellen of de ijzervoorraad te verlagen.","definition":"<p><strong>Aderlatingen</strong> zijn de behandeling van hemochromatose (ijzer verwijderen) en polycytemia vera (hematocriet verlagen, risico op trombose verminderen).</p>","image_url":"","wiki_title":"Phlebotomy","match":"aderlating|flebotomie","option_only":true},"neutropenie":{"title":"Neutropenie","short":"Neutropenie is een te laag aantal neutrofielen in het bloed, met een verhoogd risico op bacteriële en schimmelinfecties.","definition":"<p>Oorzaken van <strong>neutropenie</strong> zijn o.a. chemotherapie, geneesmiddelen (bijv. clozapine, thyreostatica, metamizol: agranulocytose), virale infecties, beenmergziekten, vitamine B12-tekort en auto-immuniteit. Bij een aantal onder 0,5 × 10⁹/L is koorts een spoedgeval.</p>","image_url":"","wiki_title":"Neutropenia","match":"neutropenie|agranulocytose","option_only":true},"melanocytaire nevus":{"title":"Melanocytaire naevus (moedervlek)","short":"Een melanocytaire naevus is een goedaardige moedervlek, ontstaan uit een opeenhoping van melanocyten.","definition":"<p><strong>Moedervlekken</strong> ontstaan vooral in de kinder- en jeugdjaren. Veel naevi of atypische naevi (groot, onregelmatig) verhogen het risico op een melanoom. Een vlek die verandert in vorm, kleur of grootte moet worden beoordeeld (ABCDE-regel).</p>","image_url":"","wiki_title":"Melanocytic nevus","match":"melanocytaire nevus|naevus|moedervlek|atypische naevus","option_only":true},"botscintigrafie":{"title":"Botscan (skeletscintigrafie)","short":"Een botscan toont met een radioactieve stof plaatsen met verhoogde botombouw, zoals metastasen, fracturen en infecties.","definition":"<p>Een <strong>botscan</strong> is gevoelig maar weinig specifiek. Hij wordt vooral gebruikt bij verdenking op botmetastasen (o.a. prostaat- en borstkanker) en occulte stressfracturen. Bij een multipel myeloom is de scan vaak negatief, omdat er weinig osteoblastactiviteit is.</p>","image_url":"","wiki_title":"Bone scintigraphy","match":"botscintigrafie|botscan","option_only":true},"auto-immuunhemolyse":{"title":"Auto-immuun hemolytische anemie","short":"Bij AIHA maakt het lichaam antistoffen tegen de eigen rode bloedcellen, die daardoor worden afgebroken; de directe antiglobulinetest (Coombs) is positief.","definition":"<p>Bij <strong>auto-immuun hemolytische anemie</strong> binden auto-antistoffen aan erytrocyten, die vervolgens vooral in de milt worden afgebroken (type II-overgevoeligheid). Bij <em>warme</em> AIHA gaat het om IgG; bij <em>koude</em> AIHA om IgM met complementactivatie.</p><p>Laboratorium: anemie met verhoogde reticulocyten, verhoogd LDH en ongeconjugeerd bilirubine, verlaagd haptoglobine, sferocyten en een positieve directe antiglobulinetest (Coombs). Oorzaken: idiopathisch, lymfoproliferatieve ziekten, SLE, infecties (Mycoplasma, EBV) of geneesmiddelen.</p>","image_url":"","wiki_title":"Autoimmune hemolytic anemia","match":"auto-immuunhemolyse","option_only":true},"hemolyse door auto-antistoffen":{"title":"Auto-immuun hemolytische anemie","short":"Bij AIHA maakt het lichaam antistoffen tegen de eigen rode bloedcellen, die daardoor worden afgebroken; de directe antiglobulinetest (Coombs) is positief.","definition":"<p>Bij <strong>auto-immuun hemolytische anemie</strong> binden auto-antistoffen aan erytrocyten, die vervolgens vooral in de milt worden afgebroken (type II-overgevoeligheid). Bij <em>warme</em> AIHA gaat het om IgG; bij <em>koude</em> AIHA om IgM met complementactivatie.</p><p>Laboratorium: anemie met verhoogde reticulocyten, verhoogd LDH en ongeconjugeerd bilirubine, verlaagd haptoglobine, sferocyten en een positieve directe antiglobulinetest (Coombs). Oorzaken: idiopathisch, lymfoproliferatieve ziekten, SLE, infecties (Mycoplasma, EBV) of geneesmiddelen.</p>","image_url":"","wiki_title":"Autoimmune hemolytic anemia","match":"hemolyse door auto-antistoffen","option_only":true},"tuberculose (mycobacterium tuberculosis)":{"title":"Tuberculose","short":"Tuberculose is een infectie met Mycobacterium tuberculosis, meestal in de longen, met langdurig hoesten, nachtzweten, gewichtsverlies en granulomen.","definition":"<p><strong>Tuberculose</strong> wordt veroorzaakt door <em>Mycobacterium tuberculosis</em> en verspreidt zich via aerosolen. Na infectie wordt de bacterie meestal ingekapseld in granulomen (latente tbc); bij verminderde afweer kan actieve ziekte ontstaan.</p><p>Longtuberculose geeft langdurig hoesten (soms met bloed), koorts, nachtzweten en gewichtsverlies; typisch zijn holtevorming in de longtoppen en granulomen met centrale <em>verkazing</em>. Behandeling met een combinatie van tuberculostatica gedurende minstens 6 maanden.</p>","image_url":"","wiki_title":"Tuberculosis","match":"tuberculose (mycobacterium tuberculosis)","option_only":true},"malaria tropica":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malaria tropica","option_only":true},"plasmodium falciparum-malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium falciparum-malaria","option_only":true},"plasmodium vivax-malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium vivax-malaria","option_only":true},"plasmodium spp":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium spp","option_only":true},"malariaparasiet":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malariaparasiet","option_only":true},"hepatitis b virus":{"title":"Hepatitis B","short":"Hepatitis B is een via bloed en seks overgedragen DNA-virus dat acute en chronische leverontsteking geeft, met risico op cirrose en levercelcarcinoom.","definition":"<p><strong>Hepatitis B</strong> wordt veroorzaakt door het hepatitis B-virus, een omhuld (gedeeltelijk dubbelstrengs) DNA-virus. Overdracht via bloed, seksueel contact en van moeder op kind rond de geboorte.</p><p>Bij volwassenen geneest de meeste acute infectie; bij pasgeborenen wordt de infectie meestal <em>chronisch</em>. Chronische hepatitis B kan leiden tot levercirrose en hepatocellulair carcinoom. Diagnostiek via serologie (HBsAg, anti-HBc, anti-HBs). Er is een effectief vaccin.</p>","image_url":"","wiki_title":"Hepatitis B","match":"hepatitis b virus","option_only":true},"beta thalassemie":{"title":"Bèta-thalassemie major","short":"Bij bèta-thalassemie major worden (vrijwel) geen bèta-globineketens gemaakt, met een ernstige anemie vanaf de eerste levensmaanden.","definition":"<p>Bij <strong>bèta-thalassemie major</strong> klonteren overtollige alfaketens in de rode voorlopercellen, met ineffectieve erytropoëse, hemolyse, beenmergexpansie (botvervormingen) en hepatosplenomegalie. Patiënten zijn transfusieafhankelijk, met ijzerstapeling als gevolg (chelatie nodig). Dragers hebben een lichte microcytaire anemie met een verhoogd HbA2.</p>","image_url":"","wiki_title":"Beta thalassemia","match":"beta thalassemie","option_only":true},"sikkelcel ziekte":{"title":"Sikkelcelziekte","short":"Sikkelcelziekte is een erfelijke hemoglobinopathie waarbij afwijkend hemoglobine (HbS) bij zuurstoftekort polymeriseert en rode bloedcellen sikkelvormig maakt.","definition":"<p>Bij <strong>sikkelcelziekte</strong> (homozygoot HbS, autosomaal recessief) verstoppen sikkelcellen kleine vaatjes en worden ze snel afgebroken. Gevolgen: pijncrises, hemolytische anemie, acute chest syndrome, herseninfarcten, miltinfarcten (functionele asplenie, infecties met gekapselde bacteriën) en priapisme. Dragerschap beschermt deels tegen malaria. Behandeling o.a. met hydroxycarbamide en transfusies.</p>","image_url":"","wiki_title":"Sickle cell disease","match":"sikkelcel ziekte","option_only":true},"vitamine b12 deficiëntie":{"title":"Vitamine B12-deficiëntie","short":"Een vitamine B12-tekort geeft een macrocytaire anemie en neurologische schade, zoals polyneuropathie en een gecombineerde strengziekte.","definition":"<p>Oorzaken van een <strong>B12-tekort</strong> zijn auto-immuungastritis (pernicieuze anemie, antistoffen tegen intrinsieke factor), maag- of ileumresectie, ziekte van Crohn, metformine, langdurig PPI-gebruik en veganistisch eten. Naast anemie ontstaan neuropathie, degeneratie van achterstrengen en piramidebanen, cognitieve stoornissen en glossitis. Methylmalonzuur en homocysteïne zijn verhoogd.</p>","image_url":"","wiki_title":"Vitamin B12 deficiency","match":"vitamine b12 deficiëntie","option_only":true},"folliculair non-hodgkin lymfoom":{"title":"Folliculair lymfoom","short":"Het folliculair lymfoom is een langzaam groeiend B-cellymfoom met een t(14;18)-translocatie en overexpressie van BCL2.","definition":"<p>Het <strong>folliculair lymfoom</strong> komt vooral bij ouderen voor en geeft vaak gegeneraliseerde, pijnloze lymfeklierzwelling die jarenlang kan wisselen. Door BCL2-overexpressie ontsnappen de cellen aan apoptose. Het is meestal niet te genezen, maar heeft een lang beloop; behandeling vaak pas bij klachten. Het kan transformeren naar een agressief lymfoom.</p>","image_url":"","wiki_title":"Follicular lymphoma","match":"folliculair non-hodgkin lymfoom","option_only":true},"humaan papillomavirus 16":{"title":"Humaan papillomavirus (HPV)","short":"HPV is een DNA-virus dat wratten veroorzaakt; hoog-risicotypes (o.a. 16 en 18) veroorzaken baarmoederhalskanker en andere kankers.","definition":"<p>Het <strong>humaan papillomavirus</strong> infecteert basale cellen van huid en slijmvlies. Laag-risicotypes (6, 11) geven wratten en condylomata acuminata. Hoog-risicotypes maken de eiwitten E6 en E7, die p53 en Rb uitschakelen; persisterende infectie kan leiden tot cervixcarcinoom en kankers van anus, vulva, penis en orofarynx. Er is een vaccin en een bevolkingsonderzoek met hrHPV-test.</p>","image_url":"","wiki_title":"Human papillomavirus infection","match":"humaan papillomavirus 16","option_only":true},"skeletfoto’s":{"title":"Skeletstatus (skeletfoto's)","short":"Bij een skeletstatus worden röntgenfoto's van het hele skelet gemaakt, bijv. bij verdenking op multipel myeloom of kindermishandeling.","definition":"<p>Een <strong>skeletstatus</strong> wordt o.a. gebruikt om lytische botlaesies op te sporen bij multipel myeloom (tegenwoordig vaak vervangen door low-dose CT of MRI), en bij jonge kinderen bij verdenking op mishandeling, om oude en nieuwe fracturen in beeld te brengen. Ook bij skeletdysplasieën wordt het gebruikt.</p>","image_url":"","wiki_title":"Skeletal survey","match":"skeletfoto’s","option_only":true},"paraproteine":{"title":"M-proteïne (paraproteïne)","short":"Een M-proteïne is een monoklonaal immunoglobuline of een lichte keten, gemaakt door één kloon van plasmacellen of B-cellen.","definition":"<p>Een <strong>M-proteïne</strong> is te zien als een smalle piek (M-piek) in het eiwitspectrum en wordt getypeerd met immunofixatie. Het komt voor bij MGUS (een voorstadium zonder klachten), het multipel myeloom, AL-amyloïdose en sommige lymfomen. Vrije lichte ketens in de urine heten Bence-Jones-eiwit.</p>","image_url":"","wiki_title":"Paraproteinemia","match":"paraproteine","option_only":true},"igm monoclonaal proteïne":{"title":"M-proteïne (paraproteïne)","short":"Een M-proteïne is een monoklonaal immunoglobuline of een lichte keten, gemaakt door één kloon van plasmacellen of B-cellen.","definition":"<p>Een <strong>M-proteïne</strong> is te zien als een smalle piek (M-piek) in het eiwitspectrum en wordt getypeerd met immunofixatie. Het komt voor bij MGUS (een voorstadium zonder klachten), het multipel myeloom, AL-amyloïdose en sommige lymfomen. Vrije lichte ketens in de urine heten Bence-Jones-eiwit.</p>","image_url":"","wiki_title":"Paraproteinemia","match":"igm monoclonaal proteïne","option_only":true},"dwarslesie":{"title":"Dwarslaesie","short":"Bij een dwarslaesie is het ruggenmerg (deels) onderbroken, met uitval van kracht, gevoel en autonome functies onder het niveau van de laesie.","definition":"<p>Een <strong>dwarslaesie</strong> ontstaat door trauma, compressie (tumor, abces, hernia), ischemie of ontsteking. Acuut kan een spinale shock optreden (slappe verlamming, areflexie), later spasticiteit. Bij hoge laesies kan autonome dysreflexie ontstaan. Een acute compressie is een neurochirurgisch spoedgeval.</p>","image_url":"","wiki_title":"Spinal cord injury","match":"dwarslesie","option_only":true},"hyperuricemie":{"title":"Urinezuur","short":"Urinezuur is het eindproduct van de purineafbraak; een te hoge spiegel kan leiden tot jicht en nierstenen.","definition":"<p><strong>Urinezuur</strong> wordt gevormd door xanthineoxidase en vooral via de nier uitgescheiden. Hyperurikemie ontstaat door verminderde uitscheiding (nierfunctiestoornis, diuretica, alcohol) of verhoogde aanmaak (celafbraak bij chemotherapie, purinerijk voedsel). Uraatkristallen veroorzaken jicht; allopurinol remt de vorming van urinezuur.</p>","image_url":"","wiki_title":"Uric acid","match":"hyperuricemie","option_only":true},"beeldvorming van het skelet":{"title":"Skeletstatus (skeletfoto's)","short":"Bij een skeletstatus worden röntgenfoto's van het hele skelet gemaakt, bijv. bij verdenking op multipel myeloom of kindermishandeling.","definition":"<p>Een <strong>skeletstatus</strong> wordt o.a. gebruikt om lytische botlaesies op te sporen bij multipel myeloom (tegenwoordig vaak vervangen door low-dose CT of MRI), en bij jonge kinderen bij verdenking op mishandeling, om oude en nieuwe fracturen in beeld te brengen. Ook bij skeletdysplasieën wordt het gebruikt.</p>","image_url":"","wiki_title":"Skeletal survey","match":"beeldvorming van het skelet","option_only":true},"x-slikfoto":{"title":"Slikfoto (bariumslik)","short":"Bij een slikfoto drinkt de patiënt contrastvloeistof terwijl röntgenopnamen worden gemaakt van slokdarm en maag.","definition":"<p>Een <strong>bariumslikfoto</strong> laat de vorm en passage van de slokdarm zien, bijvoorbeeld bij achalasie (vogelbekvorm), vernauwingen, een divertikel van Zenker of slokdarmspasmen (kurkentrekker). Bij verdenking op een perforatie wordt een wateroplosbaar contrast gebruikt.</p>","image_url":"","wiki_title":"Upper gastrointestinal series","match":"x-slikfoto","option_only":true},"ct-scan van het abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct-scan van het abdomen","option_only":true},"pet-ct thorax/abdomen":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"pet-ct thorax/abdomen","option_only":true},"choline-pet scan":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"choline-pet scan","option_only":true},"psma-pet scan":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"psma-pet scan","option_only":true},"cyclo-oxygenase inhibitors (cox-remmers)":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"cyclo-oxygenase inhibitors (cox-remmers)","option_only":true},"denguevirus":{"title":"Dengue (knokkelkoorts)","short":"Dengue is een door Aedes-muggen overgebrachte virusinfectie met hoge koorts, hevige spier- en gewrichtspijn en huiduitslag.","definition":"<p><strong>Dengue</strong> wordt veroorzaakt door een flavivirus met vier serotypes. Na een paar dagen incubatie volgen hoge koorts, hoofdpijn achter de ogen, spier- en gewrichtspijn en een rash. Een tweede infectie met een ander serotype geeft een groter risico op ernstige dengue met plasmalekkage, bloedingen en shock (door antistof-afhankelijke versterking). Behandeling is ondersteunend; NSAID's worden vermeden.</p>","image_url":"","wiki_title":"Dengue fever","match":"denguevirus","option_only":true},"myelodysplasie":{"title":"Myelodysplastisch syndroom (MDS)","short":"Bij een myelodysplastisch syndroom maakt het beenmerg afwijkende, slecht functionerende bloedcellen, met cytopenieën en een risico op AML.","definition":"<p><strong>MDS</strong> komt vooral bij ouderen voor en na eerdere chemotherapie of bestraling. Er zijn anemie (vaak macrocytair), soms trombopenie en neutropenie. Het beenmerg is vaak juist celrijk met dysplasie. Behandeling varieert van transfusies tot stamceltransplantatie.</p>","image_url":"","wiki_title":"Myelodysplastic syndrome","match":"myelodysplasie","option_only":true},"lymfadenopathie":{"title":"Lymfadenopathie","short":"Vergroting van lymfeklieren, vaak reactief bij infecties.","definition":"<p><b>Lymfadenopathie</b> is het vergroot of afwijkend zijn van lymfeklieren. Meestal reactief bij infecties (bv. in de hals bij keel-/oorontsteking), soms teken van een systeemziekte of maligniteit.</p>","image_url":"","wiki_title":"Lymphadenopathy","match":"lymfadenopathie","option_only":true},"ct thorax/abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct thorax/abdomen","option_only":true},"ct-thorax/abdomen":{"title":"CT abdomen","short":"Een CT abdomen is een röntgenscan in dwarsdoorsneden van de buik, vaak met contrast; goed voor acute buik, tumoren, abcessen en trauma.","definition":"<p>Bij een <strong>CT abdomen</strong> worden met röntgenstraling dunne dwarsdoorsneden van de buik gemaakt, meestal met intraveneus (en soms oraal) contrast.</p><p>Het geeft een overzichtelijk beeld van alle buikorganen, de darm en het retroperitoneum en wordt gebruikt bij een acute buik (bijv. perforatie, diverticulitis, appendicitis bij volwassenen), bij het stadiëren van tumoren, het opsporen van abcessen en bij trauma. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct-thorax/abdomen","option_only":true},"fecaal calprotectine":{"title":"Fecaal calprotectine","short":"Ontstekingsmarker in de ontlasting; verhoogd bij inflammatoire darmziekten, laag bij IBS.","definition":"<p><b>Fecaal calprotectine</b> is een eiwit uit neutrofielen dat in de feces wordt gemeten. Een verhoogde waarde wijst op darmontsteking (bv. de ziekte van Crohn of colitis ulcerosa) en helpt IBD van functionele klachten te onderscheiden.</p>","image_url":"","wiki_title":"Calprotectin","match":"fecaal calprotectine","option_only":true},"ecg (elektro-cardiogram)":{"title":"ECG (elektrocardiogram)","short":"Een ECG registreert de elektrische activiteit van het hart via elektroden op de huid.","definition":"<p>Een standaard <strong>12-afleidingen-ECG</strong> laat de P-top (boezemdepolarisatie), het QRS-complex (kamerdepolarisatie) en de T-top (repolarisatie) zien. Het wordt gebruikt om ritmestoornissen, geleidingsstoornissen, ischemie en infarct, hypertrofie en elektrolytstoornissen (bijv. hyperkaliëmie) op te sporen.</p>","image_url":"","wiki_title":"Electrocardiography","match":"ecg (elektro-cardiogram)","option_only":true},"laboratoriumonderzoek":{"title":"Specifiek IgE (RAST)","short":"Met een RAST of specifiek-IgE-bepaling wordt in het bloed gemeten of iemand IgE-antistoffen tegen een bepaald allergeen heeft.","definition":"<p>De bepaling van <strong>specifiek IgE</strong> is een alternatief voor de huidpriktest, bijvoorbeeld bij uitgebreid eczeem of als antihistaminica niet gestopt kunnen worden. Ook hier geldt: sensibilisatie is niet hetzelfde als allergie.</p>","image_url":"","wiki_title":"Radioallergosorbent test","match":"laboratoriumonderzoek","option_only":true},"bloedonderzoek (calcium)":{"title":"Calcium","short":"Mineraal dat essentieel is voor botmineralisatie, spiercontractie en zenuwgeleiding. Opname in de darm wordt bevorderd door 1,25-OH-vitamine D (calcitriol).","definition":"<p><strong>Calcium</strong> wordt in de dunne darm actief opgenomen onder invloed van 1,25-dihydroxyvitamine D. Het grootste deel van het lichaamscalcium ligt opgeslagen in het skelet als hydroxyapatiet.</p>","image_url":"","wiki_title":"Calcium in biology","match":"bloedonderzoek (calcium)","option_only":true},"vitamine b-12 deficiëntie":{"title":"Vitamine B12-deficiëntie","short":"Een vitamine B12-tekort geeft een macrocytaire anemie en neurologische schade, zoals polyneuropathie en een gecombineerde strengziekte.","definition":"<p>Oorzaken van een <strong>B12-tekort</strong> zijn auto-immuungastritis (pernicieuze anemie, antistoffen tegen intrinsieke factor), maag- of ileumresectie, ziekte van Crohn, metformine, langdurig PPI-gebruik en veganistisch eten. Naast anemie ontstaan neuropathie, degeneratie van achterstrengen en piramidebanen, cognitieve stoornissen en glossitis. Methylmalonzuur en homocysteïne zijn verhoogd.</p>","image_url":"","wiki_title":"Vitamin B12 deficiency","match":"vitamine b-12 deficiëntie","option_only":true},"vitamine b-12 deficientie":{"title":"Vitamine B12-deficiëntie","short":"Een vitamine B12-tekort geeft een macrocytaire anemie en neurologische schade, zoals polyneuropathie en een gecombineerde strengziekte.","definition":"<p>Oorzaken van een <strong>B12-tekort</strong> zijn auto-immuungastritis (pernicieuze anemie, antistoffen tegen intrinsieke factor), maag- of ileumresectie, ziekte van Crohn, metformine, langdurig PPI-gebruik en veganistisch eten. Naast anemie ontstaan neuropathie, degeneratie van achterstrengen en piramidebanen, cognitieve stoornissen en glossitis. Methylmalonzuur en homocysteïne zijn verhoogd.</p>","image_url":"","wiki_title":"Vitamin B12 deficiency","match":"vitamine b-12 deficientie","option_only":true},"psa":{"title":"PSA (prostaatspecifiek antigeen)","short":"PSA is een eiwit dat door prostaatcellen wordt gemaakt; een verhoogde waarde kan wijzen op prostaatkanker, maar ook op prostaatvergroting of ontsteking.","definition":"<p>Het <strong>PSA</strong> is weinig specifiek. Daarom volgt bij een verhoogde waarde eerst een risicocalculator en een MRI, en zo nodig een biopsie. Screening van alle mannen geeft veel overdiagnostiek. Na behandeling van prostaatkanker wordt PSA gebruikt om een recidief op te sporen.</p>","image_url":"","wiki_title":"Prostate-specific antigen","match":"psa|prostaatspecifiek antigeen","option_only":true},"brachytherapie met iridiumnaalden":{"title":"Brachytherapie","short":"Bij brachytherapie wordt een radioactieve bron in of vlak naast de tumor geplaatst, zodat een hoge dosis lokaal wordt gegeven.","definition":"<p><strong>Brachytherapie</strong> wordt o.a. gebruikt bij baarmoederhals-, prostaat- en slokdarmkanker, vaak in combinatie met uitwendige bestraling.</p>","image_url":"","wiki_title":"Brachytherapy","match":"brachytherapie met iridiumnaalden|brachytherapie|inwendige bestraling","option_only":true},"calprotectine":{"title":"Fecaal calprotectine","short":"Calprotectine is een eiwit uit neutrofielen; een verhoogde waarde in de ontlasting wijst op een ontsteking van de darm.","definition":"<p>Met <strong>fecaal calprotectine</strong> kan onderscheid worden gemaakt tussen een prikkelbaredarmsyndroom (normaal) en IBD (verhoogd). Het wordt ook gebruikt om de activiteit van IBD te volgen. Het is niet specifiek: ook infecties en NSAID's verhogen het.</p>","image_url":"","wiki_title":"Calprotectin","match":"calprotectine|fecaal calprotectine","option_only":true},"vitamine b12 suppletie":{"title":"Vitamine B12-deficiëntie","short":"Een vitamine B12-tekort geeft een macrocytaire anemie en neurologische schade, zoals polyneuropathie en een gecombineerde strengziekte.","definition":"<p>Oorzaken van een <strong>B12-tekort</strong> zijn auto-immuungastritis (pernicieuze anemie, antistoffen tegen intrinsieke factor), maag- of ileumresectie, ziekte van Crohn, metformine, langdurig PPI-gebruik en veganistisch eten. Naast anemie ontstaan neuropathie, degeneratie van achterstrengen en piramidebanen, cognitieve stoornissen en glossitis. Methylmalonzuur en homocysteïne zijn verhoogd.</p>","image_url":"","wiki_title":"Vitamin B12 deficiency","match":"vitamine b12 suppletie","option_only":true},"bloedonderzoek: vitamine b12":{"title":"Vitamine B12-deficiëntie","short":"Een vitamine B12-tekort geeft een macrocytaire anemie en neurologische schade, zoals polyneuropathie en een gecombineerde strengziekte.","definition":"<p>Oorzaken van een <strong>B12-tekort</strong> zijn auto-immuungastritis (pernicieuze anemie, antistoffen tegen intrinsieke factor), maag- of ileumresectie, ziekte van Crohn, metformine, langdurig PPI-gebruik en veganistisch eten. Naast anemie ontstaan neuropathie, degeneratie van achterstrengen en piramidebanen, cognitieve stoornissen en glossitis. Methylmalonzuur en homocysteïne zijn verhoogd.</p>","image_url":"","wiki_title":"Vitamin B12 deficiency","match":"bloedonderzoek: vitamine b12","option_only":true},"gabapentin":{"title":"Pregabaline","short":"Pregabaline is een middel tegen neuropathische pijn, epilepsie en gegeneraliseerde angst; het remt calciumkanalen in zenuwuiteinden.","definition":"<p><strong>Pregabaline</strong> en gabapentine binden aan de α2δ-subeenheid van calciumkanalen en verminderen de afgifte van prikkelende neurotransmitters. Bijwerkingen: sufheid, duizeligheid en oedeem; er is risico op misbruik en afhankelijkheid. Bij nierfunctiestoornis is een lagere dosis nodig.</p>","image_url":"","wiki_title":"Pregabalin","match":"gabapentin","option_only":true},"colorectaal carcinoom":{"title":"Colorectaal carcinoom","short":"Het colorectaal carcinoom is een adenocarcinoom van de dikke darm, meestal ontstaan uit een adenoom.","definition":"<p>Een tumor <strong>links</strong> geeft vaak een veranderd ontlastingspatroon en bloed bij de ontlasting; een tumor <strong>rechts</strong> vaker een ijzergebreksanemie. Risicofactoren: leeftijd, familie, IBD, Lynch-syndroom en FAP. In Nederland is er een bevolkingsonderzoek met een FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"colorectaal carcinoom|darmkanker|coloncarcinoom|rectumcarcinoom","option_only":true},"leukemie":{"title":"Leukemie","short":"Leukemie is een kwaadaardige ziekte van bloedvormende cellen, met afwijkende cellen in beenmerg en bloed.","definition":"<p>Bij <strong>acute leukemie</strong> (AML, ALL) verdringen onrijpe blasten de normale bloedaanmaak, met anemie, infecties en bloedingen. Chronische vormen (CML, CLL) verlopen langzamer. ALL is de meest voorkomende kanker bij kinderen.</p>","image_url":"","wiki_title":"Leukemia","match":"leukemie|acute leukemie|chronische leukemie","option_only":true}};
